Object.assign(window.TEM8_DICTIONARY, {"heel":{"media":{"uk":"media/uk/heel__gb_1.mp3","us":"media/us/heel__us_1.mp3","img":["media/ldoce/img/shoes.jpg"]},"oxford":{"phon":"hiːl","pos":"noun","senses":[{"en":"the back part of the foot below the ankle","cn":"脚跟；脚后跟","g":"[countable]","sc":"part of foot","ex":{"en":"Apply the cream to dry, cracked heels before bed.","cn":"睡前将霜涂抹在干燥、开裂的脚后跟上。"}},{"en":"the part of a sock, etc. that covers the heel","cn":"（袜子等的）后跟","g":"[countable]","sc":"part of sock/shoe"},{"en":"the raised part on the bottom of a shoe, boot, etc. that makes the shoe, etc. higher at the back","cn":"（鞋、靴子等的）后跟","g":"[countable]","sc":"part of sock/shoe","ex":{"en":"shoes with a low/high heel","cn":"低跟鞋；高跟鞋"}},{"en":"having the type of heel mentioned","cn":"有…后跟的","sc":"-heeled","ex":{"en":"high-heeled shoes","cn":"高跟鞋"}},{"en":"a pair of shoes that have high heels","cn":"高跟鞋","g":"[plural]","sc":"shoes","ex":{"en":"She doesn't often wear heels.","cn":"她不常穿高跟鞋。"}},{"en":"the raised part of the inside of the hand where it joins the wrist","cn":"手掌根（手掌靠近腕部的隆起部分）","g":"[countable]","sc":"part of hand"},{"en":"a man who is unpleasant to other people and cannot be trusted","cn":"卑鄙的家伙；浑蛋","g":"[countable]","lab":"old-fashioned, informal，，","sc":"unpleasant man"},{"en":"to repair the heel of a shoe, etc.","cn":"给（鞋等）修理后跟","g":"[transitive]","sc":"repair shoe","pos":"verb"},{"en":"to lean over to one side","cn":"倾侧；倾斜","g":"[intransitive]","sc":"of boat","ex":{"en":"The boat heeled over in the strong wind.","cn":"船在狂风中倾侧了。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"足跟;脚后跟;踵","en":"Your heel is the back part of your foot, just below your ankle."},{"pos":"N-COUNT 可数名词","cn":"（鞋）后跟","en":"The heel of a shoe is the raised part on the bottom at the back.","ex":{"en":"He kicked it shut with the heel of his boot.","cn":"他用靴子的后跟将它踢上。"}},{"pos":"N-PLURAL 复数名词","cn":"（女式）高跟鞋","en":"Heels are women's shoes that are raised very high at the back.","ex":{"en":"...two well-dressed ladies in high heels","cn":"两位穿着高跟鞋、打扮入时的女士"}},{"pos":"N-COUNT 可数名词","cn":"（袜子的）后跟","en":"The heel of a sock or stocking is the part that covers your heel."},{"pos":"N-COUNT 可数名词","cn":"（近腕处的）手掌根","en":"The heel of your hand is the rounded pad at the bottom of your palm.","ex":{"en":"He shoved the heel of his hand against the side of my face.","cn":"他用手掌根使劲推我的脸颊。"}},{"pos":"PHRASE 短语","cn":"紧跟在后","en":"If a person or an animal is at your heels, they are following close behind you.","ex":{"en":"She strode off down the restaurant with Cavendish following close at her heels.","cn":"她大步向餐馆里面走去，卡文迪什紧随其后。"}},{"pos":"PHRASE 短语","cn":"使听话;使就范","en":"If you bring someone to heel, you force them to obey you.","ex":{"en":"It's still not clear how the president will use his power to bring the republics to heel.","cn":"总统将如何行使自己的权力使共和党人就范仍不太清楚。"}},{"pos":"PHRASE 短语","cn":"咔嚓一声立正（敬礼或问候）","en":"If someone such as a soldier clicks their heels, they make a sound by knocking the heels of their shoes together when saluting or greeting someone.","ex":{"en":"...a courtly European who still clicked his heels when he met a lady.","cn":"遇见女士仍咔嚓一声行礼的彬彬有礼的欧洲人"}},{"pos":"PHRASE 短语","cn":"久等;空等","en":"If you are cooling your heels, someone is deliberately keeping you waiting, so that you get bored or impatient.","ex":{"en":"Cohen didn't mention that he had Ted Forstmann cooling his heels in a back room.","cn":"科恩没有提起自己让泰德·福斯特曼在后室里空等的事。"}},{"pos":"PHRASE 短语","cn":"坚持立场;固执己见","en":"If you dig your heels in or dig in your heels, you refuse to do something such as change your opinions or plans, especially when someone is trying very hard to make you do so.","ex":{"en":"It was really the British who, by digging their heels in, prevented any last-minute deal.","cn":"实际上是因为英国人拒不让步，才使得最后一刻达成协议的希望落空了。"}},{"pos":"PHRASE 短语","cn":"（时间上）紧跟…之后，紧接着","en":"If you say that one event follows hard on the heels of another or hot on the heels of another, you mean that one happens very quickly or immediately after another.","ex":{"en":"Unfortunately, bad news has come hard on the heels of good","cn":"很遗憾，好消息的后面紧跟着就是坏消息。"}},{"pos":"PHRASE 短语","cn":"紧追…之后;紧随…之后","en":"If you say that someone is hot on your heels, you are emphasizing that they are chasing you and are not very far behind you.","ex":{"en":"They sped through the American southwest with the law hot on their heels.","cn":"他们飞车穿越美国西南部，警察紧追其后。"}},{"pos":"PHRASE 短语","cn":"无聊地等;不耐烦地等待","en":"If you are kicking your heels, you are having to wait around with nothing to do, so that you get bored or impatient.","ex":{"en":"The authorities wouldn't grant us permission to fly all the way down to San Francisco, so I had to kick my heels at Tunis Airport.","cn":"当局不允许我们直飞旧金山，所以我只好在突尼斯机场不耐烦地等待。"}},{"pos":"PHRASE 短语","cn":"（尤指因生气或吃惊而）突然转身","en":"If you turn on your heel or spin on your heel, you suddenly turn round, especially because you are angry or surprised.","ex":{"en":"He simply turned on his heel and walked away.","cn":"他突然就转身走开了。"}},{"pos":"PHRASE 短语","cn":"逃走;脚底开溜","en":"If you take to your heels, you run away.","ex":{"en":"He stood, for a moment, staring defiantly back at her, then took to his heels.","cn":"他站着不服地回瞪了她一会儿，然后就逃走了。"}},{"pos":"","cn":"","en":"head over heels→see: ; to drag your heels→see: ;"},{"pos":"","cn":"","en":"相关词组：heel over"}]},"examples":[{"en":"News of rising unemployment followed hard on the heels of falling export figures.","cn":"出口数字下降之后紧接着就是失业率上升的消息。"},{"en":"He fled from the stadium with the police at his heels.","cn":"他逃离了运动场，警察在后面紧追不舍。"}]},"hell":{"oxford":{"phon":"hel","pos":"noun","senses":[{"en":"the place believed to be the home of devils and where bad people go after death","cn":"地狱","g":"[singular]","ex":{"en":"He was terrified of going to hell when he died.","cn":"他以前害怕死后下地狱。"}},{"en":"a very unpleasant experience or situation in which people suffer very much","cn":"苦难的经历；悲惨的境况","g":"[uncountable, singular]","ex":{"en":"The last three months have been hell.","cn":"过去的三个月真受罪。"}},{"en":"a swear word that some people use when they are annoyed or surprised or to emphasize something. Its use is offensive to some people.","cn":"（有人认为含冒犯意）该死，见鬼","g":"[uncountable]","lab":"North American English","ex":{"en":"Oh hell, I've burned the pan.","cn":"真该死，我把锅烧煳了。"}}]},"media":{"uk":"media/uk/hell__gb_1.mp3","us":"media/us/hell__us_1.mp3"},"examples":[{"en":"I can't really afford it, but, what the hell (= it doesn't matter), I'll get it anyway.","cn":"实在说我是买不起，但管它呢，无论如何我买定了。"},{"en":"He was a dirty player and loved to kick hell out of the opposition.","cn":"他是个不讲体育道德的球员，喜欢猛力冲撞对方。"}]},"he'll":{"media":{"uk":"media/uk/he_ll_1_gb_1.mp3","us":"media/us/he_ll_1_us_1.mp3"},"oxford":{"phon":"hiːl","pos":"short form","senses":[{"en":"he will","cn":""}]},"collins":{"senses":[{"pos":"","cn":"（he will 的常用口语形式）","en":"He'll is the usual spoken form of 'he will'.","ex":{"en":"By the time he's twenty he'll know everyone worth knowing in Washington.","cn":"到20岁时，他就会认识华盛顿所有值得认识的人。"}}]},"examples":[{"en":"Don’t worry, he’ll be there.","cn":"别担心﹐他会去那里的。"}]},"headmistress":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（中小学的）女校长","en":"A headmistress is a woman who is the head teacher of a school."}]},"media":{"uk":"media/ldoce/hwd/bre/6/headmistress0205.mp3","us":"media/ldoce/hwd/ame/3/headmistress.mp3"},"oxford":{"phon":"ˌhedˈmɪstrəs","pos":"noun","senses":[{"en":"a female head teacher, especially of a private school","cn":"（尤指私立学校的）女校长","lab":"British English"}]}},"heritage":{"media":{"uk":"media/uk/heritage__gb_1.mp3","us":"media/us/heritage__us_1.mp3"},"oxford":{"phon":"ˈherɪtɪdʒ","pos":"noun","senses":[{"en":"the history, traditions, buildings and objects that a country or society has had for many years and that are considered an important part of its character","cn":"遗产（国家或社会长期形成的文化产物，如历史、传统、建筑、物品等）","ex":{"en":"Spain’s rich cultural heritage","cn":"西班牙的丰富文化遗产"}},{"en":"a person's ethnic or religious background; the countries, cultures, religious groups, etc. that a person's parents or ancestors come from","cn":"一个人的种族或宗教背景；一个人的父母或祖先来自的国家、文化、宗教团体等","ex":{"en":"What's your heritage?","cn":"你的遗产是什么？"}},{"en":"used to describe a traditional product, brand, type of animal or plant variety, especially one that is old-fashioned, rare and of high quality","cn":"传统的，历史悠久的（尤指老式、稀有且优质）","ex":{"en":"Cotswold sheep are considered a heritage breed in Canada.","cn":"科茨沃尔德羊被认为是加拿大的传统品种。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"（国家的）遗产，传统","en":"A country's heritage is all the qualities, traditions, or features of life there that have continued over many years and have been passed on from one generation to another.","ex":{"en":"The historic building is as much part of our heritage as the paintings.","cn":"这座历史建筑和这些画一样，都是留给我们的文化遗产的一部分。"}}]},"examples":[{"en":"The building is part of our national heritage.","cn":"这个建筑是我们民族遗产的一部分。"},{"en":"Spain's rich cultural heritage","cn":"西班牙的丰富文化遗产"}]},"henry":{"media":{"uk":"media/uk/henry__gb_1.mp3","us":"media/us/henry__us_1.mp3"},"oxford":{"phon":"ˈhenri","pos":"noun","senses":[{"en":"a unit for measuring the inductance in an electric circuit","cn":"亨，亨利（电感单位）"},{"en":"a first name for boys","cn":"亨利（男子名）","pos":""}]}},"herself":{"media":{"uk":"media/uk/herself__gb_1.mp3","us":"media/us/herself__us_1.mp3"},"oxford":{"phon":"hɜːˈself","pos":"pronoun","senses":[{"en":"used when the woman or girl who performs an action is also affected by it","cn":"（用作女性的反身代词）她自己，自己","ex":{"en":"She hurt herself.","cn":"她弄伤了自己。"}},{"en":"used to emphasize the female subject or object of a sentence","cn":"（强调句中的女性主语或宾语）","ex":{"en":"She told me the news herself.","cn":"是她本人告诉我这个消息的。"}}]},"collins":{"senses":[{"pos":"PRON-REFL 反身代词","cn":"她自己（指女性或雌性动物）","en":"You use herself to refer to a woman, girl, or female animal.","ex":{"en":"She let herself out of the room","cn":"她走出了房间。"}},{"pos":"PRON-REFL 反身代词","cn":"（书面英语中泛指人）他自己，她自己（有些人不喜欢这种用法，更倾向于使用 himself or herself 或 themselves）","en":"In written English, herself is sometimes used to refer to a person without saying whether that person is a man or a woman. Some people dislike this use and prefer to use 'himself or herself' or 'themselves'.","ex":{"en":"How can anyone blame her for actions for which she feels herself to be in no way responsible?","cn":"她认为自己对这些行动不负有责任，别人怎么还能因此而责备她呢？"}},{"pos":"PRON-REFL 反身代词","cn":"（指国家或民族）她自己，它自己","en":"Herself is sometimes used to refer to a country or nation.","ex":{"en":"Britain's dream of herself began to fade.","cn":"不列颠民族的梦想开始渐渐幻灭。"}},{"pos":"PRON-REFL 反身代词","cn":"（指汽车、机器或船）她自己，它自己","en":"People sometimes use herself to refer to a car, machine, or ship.","ex":{"en":"The ship adjusted herself to the roll and rhythm of the sea.","cn":"船随着海水的起伏节奏时起时落。"}},{"pos":"PRON-REFL-EMPH 强调反身代词","cn":"（用于加强语气，有时代替 her 作动词或介词的宾语）她本人，它本身","en":"You use herself to emphasize the person or thing that you are referring to. Herself is sometimes used instead of 'her' as the object of a verb or preposition.","ex":{"en":"She's so beautiful herself","cn":"她本人是如此美丽。"}}]},"examples":[{"en":"She wants a room all to herself.","cn":"她想要一个完全属于自己的房间。"},{"en":"She didn't seem quite herself this morning.","cn":"她今天早上好像有点不太对劲。"}]},"heated":{"oxford":{"phon":"ˈhiːtɪd","pos":"adjective","senses":[{"en":"full of anger and excitement","cn":"愤怒的；激烈的；十分激动的","ex":{"en":"a heated argument/debate","cn":"激烈的争论／辩论"}},{"en":"made warmer using a heater","cn":"（用加热器）加热了的","ex":{"en":"a heated swimming pool","cn":"温水游泳池"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（讨论或争吵）激烈的","en":"A heated discussion or quarrel is one where the people involved are angry and excited.","ex":{"en":"It was a very heated argument and they were shouting at each other","cn":"争论非常激烈，他们相互之间大喊大叫。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"发怒的;激动的","en":"If someone gets heated about something, they get angry and excited about it.","ex":{"en":"You will understand that people get a bit heated about issues such as these","cn":"你要明白，对于这类问题人们不免会有些激动。"}}]},"media":{"uk":"media/uk/heated__gb_1.mp3","us":"media/us/heated__us_1.mp3"},"examples":[{"en":"‘You had no right!’ she said heatedly. “","cn":"你没有权利！”她愤怒地说。"},{"en":"She became very heated.","cn":"她不禁怒火中烧。"}],"base":"heat"},"hebrew":{"media":{"uk":"media/uk/hebrew__gb_1.mp3","us":"media/us/hebrew__us_1.mp3"},"oxford":{"phon":"ˈhiːbruː","pos":"noun","senses":[{"en":"a member of an ancient people living in what is now Israel and Palestine. Their writings and traditions form the basis of the Jewish religion.","cn":"希伯来人"},{"en":"the language traditionally used by the Hebrew people","cn":"希伯来语"},{"en":"a modern form of the Hebrew language which is the official language of modern Israel","cn":"现代希伯来语（现代以色列的官方语言）"},{"en":"of or connected with the Hebrew language or people","cn":"希伯来语的；希伯来人的","pos":"adjective"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"希伯来语","en":"Hebrew is a language that was spoken by Jews in former times. A modern form of Hebrew is spoken now in Israel.","ex":{"en":"He is a fluent speaker of Hebrew.","cn":"他说一口流利的希伯来语。"}},{"pos":"N-COUNT 可数名词","cn":"希伯来人（旧时指犹太人）","en":"In former times, a Hebrew was a Jewish person.","ex":{"en":"...the exodus of the Hebrews from Egypt.","cn":"希伯来人出埃及之事"}},{"pos":"ADJ 形容词","cn":"希伯来语的;希伯来人的","en":"Hebrew means belonging to or relating to the Hebrew language or people.","ex":{"en":"...the respected Hebrew newspaper Haaretz","cn":"受到尊崇的希伯来语报纸《国土报》"}}]}},"heavily":{"media":{"uk":"media/uk/heavily__gb_1.mp3","us":"media/us/heavily__us_1.mp3"},"oxford":{"phon":"ˈhevɪli","pos":"adverb","senses":[{"en":"to a great degree; in large amounts","cn":"在很大程度上；大量地","ex":{"en":"It was raining heavily.","cn":"雨下得很大。"}},{"en":"with a lot of force or effort","cn":"以猛力；沉重地","ex":{"en":"She fell heavily to the ground.","cn":"她重重地摔倒在地。"}},{"en":"with a large, solid and strong body","cn":"身材壮实"},{"en":"slowly and loudly","cn":"缓慢又高声地","ex":{"en":"She was now breathing heavily.","cn":"她喘着粗气。"}},{"en":"in a slow way that sounds as though you are worried or sad","cn":"缓慢而忧郁地；悲伤地","ex":{"en":"He sighed heavily.","cn":"他长叹了一声。"}},{"en":"in a way that makes you feel uncomfortable or anxious","cn":"令人心情沉重","ex":{"en":"Silence hung heavily in the room.","cn":"房间里寂若死灰。"}},{"en":"full of or loaded with heavy things","cn":"装满（或装载）重物的；重载的","ex":{"en":"a heavily loaded van","cn":"满载重物的货车"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"缓慢沉痛地;费力地;沉重地","en":"If someone says something heavily, they say it in a slow way which shows a feeling such as sadness, tiredness, or annoyance.","ex":{"en":"'I didn't even think about her,' he said heavily.","cn":"“我甚至没有想过她，”他沉重地说道。"}}]},"examples":[{"en":"The burden of guilt weighed heavily on his mind.","cn":"愧疚之情压得他透不过气来。"},{"en":"They are both heavily involved in politics.","cn":"他们俩都深深卷入政治中。"}]},"hear":{"media":{"uk":"media/uk/hear__gb_1.mp3","us":"media/us/hear__us_1.mp3"},"oxford":{"phon":"hɪə(r)","pos":"verb","senses":[{"en":"to be aware of sounds with your ears","cn":"听见；听到","g":"[intransitive, transitive]","ex":{"en":"I can't hear very well.","cn":"我听觉不太好。"}},{"en":"to listen or pay attention to somebody/something","cn":"听；注意听；倾听","g":"[transitive]","ex":{"en":"Did you hear that play on the radio last night?","cn":"你昨晚收听了那出广播剧吗？"}},{"en":"to be told about something","cn":"听说；得知","g":"[intransitive, transitive]","ex":{"en":"Haven't you heard? She resigned.","cn":"你还没听说吗？她辞职了。"}},{"en":"to listen to and judge a case in court","cn":"审理；听审","g":"[transitive]","ex":{"en":"The appeal was heard in private.","cn":"这件上诉案不公开审理。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"听见;听到","en":"When you hear a sound, you become aware of it through your ears.","ex":{"en":"She heard no further sounds","cn":"她再没有听到别的声音了。"}},{"pos":"VERB 动词","cn":"听，聆听（演讲、音乐等）","en":"If you hear something such as a lecture or a piece of music, you listen to it.","ex":{"en":"You can hear commentary on the match in about half an hour's time","cn":"大约半小时后就能听到这场比赛的解说了。"}},{"pos":"VERB 动词","cn":"脑际响起","en":"If you say that you can hear someone saying something, you mean that you are able to imagine hearing it.","ex":{"en":"Can't you just hear John Motson now?","cn":"你脑海里现在没有响起约翰·莫特森的声音吗？"}},{"pos":"VERB 动词","cn":"（法官或法庭）审理（案件），听取（证词）","en":"When a judge or a court of law hears a case, or evidence in a case, they listen to it officially in order to make a decision about it.","ex":{"en":"The jury have heard evidence from defence witnesses","cn":"陪审团已经听取了辩方证人的证词。"}},{"pos":"VERB 动词","cn":"接到…的信（或电话）","en":"If you hear from someone, you receive a letter or telephone call from them.","ex":{"en":"Drop us a line, it's always great to hear from you","cn":"给我们写封短信，能收到你的信总是让人很高兴。"}},{"pos":"VERB 动词","cn":"（辩论或讨论中）倾听（意见或情况）","en":"In a debate or discussion, if you hear from someone, you listen to them giving their opinion or information.","ex":{"en":"What are you hearing from people there?","cn":"你在那里都听到人们说了些什么？"}},{"pos":"VERB 动词","cn":"听说;得知;了解到","en":"If you hear some news or information about something, you find out about it by someone telling you, or from the radio or television.","ex":{"en":"My mother heard of this school through Leslie","cn":"我母亲是从莱斯利那里知道这所学校的。"}},{"pos":"VERB 动词","cn":"听说（过…）;（对…）有一点了解","en":"If you have heard of something or someone, you know about them, but not in great detail.","ex":{"en":"Many people haven't heard of reflexology.","cn":"很多人没听说过反射学。"}},{"pos":"PHRASE 短语","cn":"已经知道;早就听说过","en":"If you say that you have heard something before, you mean that you are not interested in it, or do not believe it, or are not surprised about it, because you already know about it or have experienced it.","ex":{"en":"Furness shrugs wearily. He has heard it all before","cn":"弗内斯疲倦地耸了耸肩。这事他早就全知道了。"}},{"pos":"CONVENTION 惯用语","cn":"“听见没有？”“你听到我的话了吗？”（要求对方注意听自己的话）","en":"If you say 'Do you hear?' or 'Did you hear me?' to someone, you are telling them in an angry or forceful way to pay attention to what you are saying.","ex":{"en":"If you don't get out I'll call the police. Do you hear?","cn":"如果你不出去，我就要报警了。听见没有？"}},{"pos":"CONVENTION 惯用语","cn":"说得对！说得好！（政治辩论或公众大会上对讲话人表示赞同的喝彩声）","en":"During political debates and public meetings, people sometimes say 'Hear hear!' to express their agreement with what the speaker is saying."},{"pos":"PHRASE 短语","cn":"太吵了;吵死人了","en":"If you say that you can't hear yourself think, you are complaining and emphasizing that there is a lot of noise, and that it is disturbing you or preventing you from doing something.","ex":{"en":"For God's sake shut up. I can't hear myself think!","cn":"看在老天爷的份上，闭嘴吧。吵死我了！"}},{"pos":"PHRASE 短语","cn":"不同意;不允许","en":"If you say that you won't hear of someone doing something, you mean that you refuse to let them do it.","ex":{"en":"I've always wanted to be an actor but Dad wouldn't hear of it","cn":"我一直想当个演员，但爸爸不同意。"}},{"pos":"","cn":"","en":"you could have heard a pin drop→see: ;"},{"pos":"","cn":"","en":"相关词组：hear out"}]},"examples":[{"en":"The last I heard of him he was living in Glasgow.","cn":"我最后一次听到他的消息时，他住在格拉斯哥。"},{"en":"If we don't get her a dog we'll never hear the end of it.","cn":"我们要是不给她弄条狗来，这事就没完没了。"}]},"hearing-impaired":{"collins":{"senses":[{"pos":"","cn":"听觉受损的;有听力障碍的","en":"A hearing-impaired person cannot hear as well as most people.","ex":{"en":"Some hearing-impaired children may work harder to overcome their handicap.","cn":"一些有听障的儿童可能需要花更大的力气来克服这一缺陷。"}}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41hearing-impair.mp3","us":"media/ldoce/hwd/ame/8/laadhearing-impaired.mp3"},"oxford":{"phon":"ˌhɪərɪŋ ɪmˈpeəd","pos":"adjective","senses":[{"en":"not able to hear well; partly or completely deaf","cn":"有听觉障碍的"}]}},"he's":{"media":{"uk":"media/uk/he_s_1_gb_1.mp3","us":"media/us/he_s_1_us_1.mp3"},"oxford":{"phon":"hiːz","pos":"short form","senses":[{"en":"he is","cn":""},{"en":"he has","cn":""}]},"collins":{"senses":[{"pos":"","cn":"（尤当 has 为助动词时，he is 或 he has 的常用口语形式）","en":"He's is the usual spoken form of 'he is' or 'he has', especially when 'has' is an auxiliary verb.","ex":{"en":"He's working maybe twenty-five hours a week","cn":"他一周工作大概25个小时。"}}]},"examples":[{"en":"He’s a writer.","cn":"他是一位作家。"},{"en":"He’s reading.","cn":"他正在看书。"}]},"he'd":{"media":{"uk":"media/uk/he_d_1_gb_1.mp3","us":"media/us/he_d_1_us_1.mp3"},"oxford":{"phon":"hiːd","pos":"short form","senses":[{"en":"he had","cn":""},{"en":"he would","cn":""}]},"collins":{"senses":[{"pos":"","cn":"（尤当 had 为助动词时，he had 的常用口语形式）","en":"He'd is the usual spoken form of 'he had', especially when 'had' is an auxiliary verb.","ex":{"en":"Steve had told her that he'd been in an accident on Wednesday night","cn":"史蒂夫已经告诉过她自己周三晚上出了事故。"}},{"pos":"","cn":"（he would 的口语形式）","en":"He'd is a spoken form of 'he would'.","ex":{"en":"He'd come into the clubhouse every day.","cn":"他每天都会来俱乐部会所。"}}]},"examples":[{"en":"By the time I got there he’d gone.","cn":"我到达那里时﹐他已经走了。"},{"en":"I’m sure he’d help if he could.","cn":"我相信如果他能帮忙的话一定会帮的。"}]},"heat":{"media":{"uk":"media/uk/heat__gb_1.mp3","us":"media/us/heat__us_1.mp3"},"oxford":{"phon":"hiːt","pos":"noun","senses":[{"en":"the quality of being hot","cn":"热","g":"[uncountable, singular]","sc":"being hot/temperature","ex":{"en":"Heat rises.","cn":"热空气向上升。"}},{"en":"heat seen as a form of energy that is transferred from one object or substance to another as a result of a difference in temperature","cn":"热量；热力","g":"[uncountable]","lab":"physics","sc":"being hot/temperature","ex":{"en":"Being a metal, aluminium readily conducts heat.","cn":"铝是一种金属，导热良好。"}},{"en":"the level of temperature","cn":"温度","g":"[uncountable, countable, usually singular]","sc":"being hot/temperature","ex":{"en":"Test the heat of the water before getting in.","cn":"入水之前先试一试水温。"}},{"en":"hot weather; the hot conditions in a building, vehicle, etc.","cn":"暑热；（建筑物、车辆等中的）高温，炎热环境","g":"[uncountable]","sc":"being hot/temperature","ex":{"en":"You should not go out in the heat of the day (= at the hottest time).","cn":"你不应该在天最热的时候外出。"}},{"en":"a source of heat, especially one that you cook food on","cn":"炉灶；灶眼；炉火","g":"[uncountable]","sc":"for cooking","ex":{"en":"Return the pan to the heat and stir.","cn":"把锅放回灶上再搅拌。"}},{"en":"the process of supplying heat to a room or building; a system used to do this","cn":"供暖；供暖系统；暖气设备","g":"[uncountable]","lab":"especially North American English","sc":"in building/room","ex":{"en":"The heat wasn't on and the house was freezing.","cn":"暖气没有开，房子里冰冷。"}},{"en":"a spicy quality in food that makes your mouth feel as if it is burning","cn":"辣","sc":"in spicy food","ex":{"en":"Chilli peppers add taste and heat to food.","cn":"辣椒能给食物提味并增加辣味。"}},{"en":"strong feelings, especially of anger or excitement","cn":"强烈感情；（尤指）愤怒，激动","g":"[uncountable]","sc":"strong feelings","ex":{"en":"‘No, I won't,’ he said with heat in his voice.","cn":"“不，我绝不。”他怒气冲冲地说。"}},{"en":"pressure on somebody to do or achieve something","cn":"压力；逼迫","g":"[uncountable]","sc":"pressure","ex":{"en":"The heat is on now that the election is only a week away.","cn":"离选举只有一个星期了，因此大家开始感觉到有压力了。"}},{"en":"one of a series of races or competitions, the winners of which then compete against each other in the next part of the competition","cn":"预赛；分组赛","g":"[countable]","sc":"race","ex":{"en":"a qualifying heat","cn":"资格赛"}},{"en":"to make something hot or warm; to become hot or warm","cn":"加热；变热；（使）变暖","lab":"British English","ex":{"en":"Heat the oil and add the onions.","cn":"把油烧热后加入洋葱。"},"pos":"verb"},{"en":"a UK magazine published since 1999, that contains photographs and articles about famous people and their private lives. It also covers fashion and beauty, entertainment, etc.","cn":"自1999年以来发行的英国杂志，其中包含有关名人及其私生活的照片和文章。它还涵盖时尚和美容，娱乐等。","pos":""}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"把…加热;使升温","en":"When you heat something, you raise its temperature, for example by using a flame or a special piece of equipment.","ex":{"en":"Meanwhile, heat the tomatoes and oil in a pan.","cn":"同时，在平底锅里将西红柿和油加热。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"热;高温","en":"Heat is warmth or the quality of being hot.","ex":{"en":"The seas store heat and release it gradually during cold periods","cn":"海洋储存热量，并在寒冷季节里慢慢地把它释放出来。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"炎热;高温天气","en":"The heat is very hot weather.","ex":{"en":"As an asthmatic, he cannot cope with the heat and humidity","cn":"他患有哮喘病，经不起高温和潮湿。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"温度;热度","en":"The heat of something is the temperature of something that is warm or that is being heated.","ex":{"en":"Warm the milk to blood heat","cn":"将牛奶热至人体温度。"}},{"pos":"N-SING 单数名词","cn":"热源;炉灶;暖气","en":"You use heat to refer to a source of heat, for example a cooking ring or the heating system of a house.","ex":{"en":"Immediately remove the pan from the heat","cn":"马上把平底锅从灶上端下来。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"强烈的感情;（尤指）愤怒，激动","en":"You use heat to refer to a state of strong emotion, especially of anger or excitement.","ex":{"en":"It was all done in the heat of the moment and I have certainly learned by my mistake","cn":"所有的一切都是在一怒之下干的，我无疑已经从自己的错误中吸取了教训。"}},{"pos":"N-SING 单数名词","cn":"（某活动）最激烈的时刻","en":"The heat of a particular activity is the point when there is the greatest activity or excitement.","ex":{"en":"Last week, in the heat of the election campaign, the Prime Minister left for America.","cn":"上周，当竞选活动进行到白热化时，首相启程去了美国。"}},{"pos":"N-COUNT 可数名词","cn":"预赛;分组赛","en":"A heat is one of a series of races or competitions. The winners of a heat take part in another race or competition, against the winners of other heats.","ex":{"en":"...the heats of the men's 100m breaststroke.","cn":"男子100米蛙泳预赛"}},{"pos":"PHRASE 短语","cn":"（雌性动物）正在发情（美国英语中作 in heat）","en":"When a female animal is on heat in British English, or in heat in American English, she is in a state where she is ready to mate with a male animal, as this will probably result in her becoming pregnant."},{"pos":"","cn":"","en":"相关词组：heat up"}]},"examples":[{"en":"He did well in the heats; hopefully he'll do as well in the final.","cn":"他在预赛中成绩很好，且有望在决赛中也有同样出色的表现。"},{"en":"The heat is on now that the election is only a week away.","cn":"离选举只有一个星期了，因此大家开始感觉到有压力了。"}]},"hectic":{"media":{"uk":"media/uk/hectic__gb_1.mp3","us":"media/us/hectic__us_1.mp3"},"oxford":{"phon":"ˈhektɪk","pos":"adjective","senses":[{"en":"very busy; full of activity","cn":"忙碌的；繁忙的","ex":{"en":"to lead a hectic life","cn":"生活十分忙碌"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"紧张忙碌的;忙乱的","en":"A hectic situation is one that is very busy and involves a lot of rushed activity.","ex":{"en":"Despite his hectic work schedule, Benny has rarely suffered poor health","cn":"尽管工作繁忙，本尼却少有身体不好的时候。"}}]},"examples":[{"en":"a hectic schedule","cn":"安排很满的日程表"},{"en":"to lead a hectic life","cn":"生活十分忙碌"}]},"headed":{"media":{"uk":"media/uk/headed__gb_1.mp3","us":"media/us/headed__us_1.mp3"},"oxford":{"phon":"ˈhedɪd","pos":"adjective","senses":[{"en":"having the name and address of a person, an organization, etc. printed at the top","cn":"顶端印有名称和地址的；有信头的","ex":{"en":"headed notepaper","cn":"有信头的便笺纸"}},{"en":"having the type of head or number of heads mentioned","cn":"有…头的；有…个头的","ex":{"en":"a bald-headed man","cn":"秃顶男子"}}]},"examples":[{"en":"headed notepaper","cn":"有信头的便笺纸"},{"en":"a bald-headed man","cn":"秃顶男子"}],"base":"head"},"helping":{"media":{"uk":"media/uk/helping__gb_1.mp3","us":"media/us/helping__us_1.mp3"},"oxford":{"phon":"ˈhelpɪŋ","pos":"noun","senses":[{"en":"an amount of food given to somebody at a meal","cn":"（进餐时的）一份食物，一客食物","ex":{"en":"a small/generous helping","cn":"一小份／一大份食物"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（食物的）一份，一客","en":"A helping of food is the amount of it that you get in a single serving.","ex":{"en":"She gave them extra helpings of ice-cream.","cn":"她又给了他们几份冰激凌。"}},{"pos":"N-COUNT 可数名词","cn":"（尤指某种特性的）一些，一定量","en":"You can refer to an amount of something, especially a quality, as a helping of that thing.","ex":{"en":"It took a generous helping of entrepreneurial confidence to persevere during this incident.","cn":"在这一事件中坚持下来是有了充足的创业信心的。"}}]},"examples":[{"en":"We all had a second helping of pie.","cn":"我们又都吃了一份馅饼。"},{"en":"a small/generous helping","cn":"一小份/一大份食物"}],"base":"help"},"headquarters":{"oxford":{"phon":"ˌhedˈkwɔːtəz","pos":"noun","senses":[{"en":"a place from which an organization or a military operation is controlled; the people who work there","cn":"总部；总公司；大本营；司令部","ex":{"en":"The firm’s headquarters is/are in London.","cn":"公司总部设在伦敦。"}}]},"collins":{"senses":[{"pos":"N-SING-COLL 单数集合名词","cn":"总部;总公司","en":"The headquarters of an organization are its main offices.","ex":{"en":"...fraud squad officers from London's police headquarters","cn":"伦敦警察总部诈骗案调查组的警官们"}}]},"media":{"uk":"media/uk/headquarters__gb_1.mp3","us":"media/us/headquarters__us_1.mp3"},"examples":[{"en":"Several companies have their headquarters in the area.","cn":"有几家公司总部设在这个地区。"},{"en":"Headquarters in Dublin has/have agreed.","cn":"都柏林总部已经同意了。"}]},"hens":{"lemma":"hen"},"heavy":{"media":{"uk":"media/uk/heavy__gb_1.mp3","us":"media/us/heavy__us_1.mp3","img":["media/ldoce/img/heavy.jpg"]},"oxford":{"phon":"ˈhevi","pos":"adjective","senses":[{"en":"weighing a lot; difficult to lift or move","cn":"重的；沉的","lab":"especially North American English","sc":"weighing a lot","ex":{"en":"a heavy weight/load","cn":"重物；重载"}},{"en":"more or worse than usual in amount, degree, etc.","cn":"（在数量、程度等方面）超出一般的，比一般严重的","sc":"worse than usual","ex":{"en":"the noise of heavy traffic","cn":"繁忙交通的噪声"}},{"en":"doing the thing mentioned more, or more deeply, than usual","cn":"（做某事）过量的，超出一般的，过度的","g":"[only before noun]","sc":"drinker/smoker/sleeper","ex":{"en":"a heavy drinker/smoker","cn":"酒瘾／烟瘾大的人"}},{"en":"large and solid","cn":"重型的；大型的","sc":"solid","ex":{"en":"big, dark rooms full of heavy furniture","cn":"装满厚实家具、又大又暗的房间"}},{"en":"thick","cn":"厚的","sc":"material","ex":{"en":"heavy curtains","cn":"厚窗帘"}},{"en":"full of or loaded with something","cn":"充满，满载（某物）","lab":"literary","sc":"full of something","ex":{"en":"trees heavy with apples","cn":"挂满苹果的树"}},{"en":"large and powerful","cn":"重型的；大型的","g":"[usually before noun]","sc":"machines","ex":{"en":"a wide range of engines and heavy machinery/equipment","cn":"各种各样的发动机和重型机械／设备"}},{"en":"involving a lot of work or activity; very busy","cn":"工作（或活动）多的；繁忙的","g":"[usually before noun]","sc":"busy","ex":{"en":"a heavy schedule","cn":"安排很紧的日程"}},{"en":"hard, especially because it requires a lot of physical strength","cn":"辛苦的；费力的","sc":"work","ex":{"en":"heavy lifting","cn":"搬抬重物"}},{"en":"falling or hitting something with a lot of force","cn":"沉重的；猛烈的","sc":"fall/hit","ex":{"en":"a heavy fall/blow","cn":"重重的跌落／一击"}},{"en":"large in amount or very solid","cn":"量大的；厚实的","sc":"meal/food","ex":{"en":"a heavy lunch/dinner/meal","cn":"丰盛的午餐／正餐／一餐"}},{"en":"carrying heavy weapons","cn":"携带重武器的；重装的","g":"[only before noun]","sc":"army","ex":{"en":"the heavy infantry/cavalry","cn":"重步兵；重骑兵"}},{"en":"loud and deep","cn":"响而深沉的","sc":"sound","ex":{"en":"heavy breathing","cn":"粗重的呼吸声"}},{"en":"using a lot of something","cn":"使用很多…的；耗费…的","lab":"informal","sc":"using a lot","ex":{"en":"Older cars are heavy on gas.","cn":"老旧的汽车耗油多。"}},{"en":"serious; difficult to understand or enjoy","cn":"严肃的；难懂的；艰涩的","lab":"usually disapproving","sc":"serious/difficult","ex":{"en":"We found the play very heavy.","cn":"我们觉得这部戏很艰涩。"}},{"en":"dangerous because of big waves, etc.","cn":"危险的；汹涌的","sc":"sea/ocean","ex":{"en":"strong winds and heavy seas","cn":"风急浪高"}},{"en":"hot and without enough fresh air, in a way that feels unpleasant","cn":"闷热的；沉闷的","sc":"air/weather","ex":{"en":"It's very heavy—I think there'll be a storm.","cn":"天气很闷热，我觉得暴风雨要来了。"}},{"en":"wet, sticky and difficult to dig or to move over","cn":"黏重难挖的；泥泞难行的","sc":"soil"},{"en":"very strict and severe","cn":"苛刻的；严厉的","sc":"strict","ex":{"en":"Don't be so heavy on her—it wasn't her fault.","cn":"别对她这么苛刻，这不是她的过错。"}},{"en":"a large strong man whose job is to protect a person or place, often using violence","cn":"保镖；打手","g":"[countable]","lab":"informal","ex":{"en":"He lunged at the minister, but was soon pulled to the ground by a couple of heavies.","cn":"他突然冲向部长，但很快被几个保镖压倒在地。"},"pos":"noun"},{"en":"strong beer, especially bitter","cn":"烈性啤酒；（尤指）苦啤酒","g":"[uncountable]","lab":"Scottish English","ex":{"en":"a pint of heavy","cn":"一品脱烈性啤酒"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"重的;沉的","en":"Something that is heavy weighs a lot.","ex":{"en":"These scissors are awfully heavy","cn":"这把剪刀太沉了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有…重的","en":"You use heavy to ask or talk about how much someone or something weighs.","ex":{"en":"How heavy are you?","cn":"你有多重？"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"大量的;重大的;严重的;强烈的;剧烈的","en":"Heavy means great in amount, degree, or intensity.","ex":{"en":"Heavy fighting has been going on","cn":"激烈的战斗一直持续不断。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"结实的;粗大的;厚重的","en":"Someone or something that is heavy is solid in appearance or structure, or is made of a thick material.","ex":{"en":"We talk in her Belgrade flat, full of heavy old brown furniture","cn":"我们在她位于贝尔格莱德的公寓里进行了交谈，那屋里满是结实的老式棕色家具。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（质地）黏重的","en":"A heavy substance is thick in texture.","ex":{"en":"It is advisable to mix coarse grit into heavy soil to improve drainage.","cn":"建议将粗砂掺到黏重的土壤里，以提高排水性能。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（饭菜）量大的，难消化的","en":"A heavy meal is large in amount and often difficult to digest.","ex":{"en":"He had been feeling drowsy, the effect of an unusually heavy meal.","cn":"他一直感到昏昏沉沉的，这是吃了一顿超级大餐的结果。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"充满…的;装满…的","en":"Something that is heavy with things is full of them or loaded with them.","ex":{"en":"The air is heavy with moisture","cn":"空气的湿度很大。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（呼吸）粗重的，深沉的","en":"If a person's breathing is heavy, it is very loud and deep.","ex":{"en":"Her breathing became slow and heavy.","cn":"她的呼吸变得缓慢而粗重。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（动作）用力的，猛烈的","en":"A heavy movement or action is done with a lot of force or pressure.","ex":{"en":"...a heavy blow on the back of the skull","cn":"后脑勺遭到的一记重击"}},{"pos":"ADJ 形容词","cn":"（机器、武器等）重型的，大型的","en":"A heavy machine or piece of military equipment is very large and very powerful.","ex":{"en":"...government militia backed by tanks and heavy artillery.","cn":"以坦克和重型大炮为后盾的政府国民军"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"繁忙的;(日程)排满的","en":"If you describe a period of time or a schedule as heavy, you mean it involves a lot of work.","ex":{"en":"It's been a heavy day and I'm tired","cn":"忙了一天，我累坏了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"费力的;繁重的","en":"Heavy work requires a lot of strength or energy.","ex":{"en":"The business is thriving and Philippa employs two full-timers for the heavy work.","cn":"业务蒸蒸日上，菲莉帕雇用了两个全职员工来应付繁重的工作。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"耗费…多的;大量使用…的","en":"If you say that something is heavy on another thing, you mean that it uses a lot of that thing or too much of that thing.","ex":{"en":"Tanks are heavy on fuel and destructive to roads.","cn":"坦克要耗费大量的燃料，而且会破坏道路。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(空气、天气等）阴沉的，闷热的","en":"Air or weather that is heavy is unpleasantly still, hot, and damp.","ex":{"en":"The outside air was heavy and moist and sultry.","cn":"外面的空气沉滞、潮湿而闷热。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（表情）沉痛的，疲惫呆滞的，阴郁的","en":"If you describe a person's face as heavy, you mean that it looks sad, tired, or unfriendly.","ex":{"en":"Many of them were policemen, with their heavy faces and cropped hair.","cn":"他们中有很多人表情阴郁，留着平头，一看就是警察。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（心情）沉重的，悲伤的","en":"If your heart is heavy, you are sad about something.","ex":{"en":"Mr Maddison handed over his resignation letter with a heavy heart.","cn":"麦迪逊先生心情沉重地递上自己的辞呈。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（形势）棘手的，难应付的","en":"A situation that is heavy is serious and difficult to cope with.","ex":{"en":"I don't want any more of that heavy stuff.","cn":"我再也不想碰那种麻烦事了。"}},{"pos":"N-COUNT 可数名词","cn":"（雇作保镖或打手的）彪形大汉","en":"A heavy is a large strong man who is employed to protect a person or place, often by using violence.","ex":{"en":"They had employed heavies to evict shop squatters from neighbouring sites.","cn":"他们雇了一些彪形大汉，将附近私自占点的商贩都赶走了。"}},{"pos":"","cn":"","en":"to make heavy weather of something→see: ; a heavy hand→see: ;"}]},"examples":[{"en":"They started shouting at me. It got very heavy.","cn":"他们开始对我大喊大叫，情势变得很激烈。"},{"en":"She was struggling with a heavy suitcase.","cn":"她正费力地拎着一只沉重的手提箱。"}]},"her":{"media":{"uk":"media/uk/her__gb_1.mp3","us":"media/us/her__us_1.mp3"},"oxford":{"phon":"hə(r)","pos":"pronoun","senses":[{"en":"used as the object of a verb, after the verb be or after a preposition to refer to a woman or girl who has already been mentioned or is easily identified","cn":"（用作动词或介词的宾语，或作表语）她","lab":"British English","ex":{"en":"We're going to call her Sophie.","cn":"我们将给她起名索菲。"}},{"en":"of or belonging to a woman or girl who has already been mentioned or is easily identified","cn":"她的","ex":{"en":"Meg loves her job.","cn":"梅格热爱她的工作。"},"pos":"determiner"}]},"collins":{"senses":[{"pos":"PRON-SING 单数型代词","cn":"她;（雌性动物）它","en":"You use her to refer to a woman, girl, or female animal.","ex":{"en":"I went in the room and told her I had something to say to her","cn":"我走进房间，告诉她我有话要和她说。"}},{"pos":"PRON-SING 单数型代词","cn":"（书面英语中不区分性别地泛指人）他或她（一些人不喜欢这种用法，更倾向于使用 him or her 或 them）","en":"In written English, her is sometimes used to refer to a person without saying whether that person is a man or a woman. Some people dislike this use and prefer to use 'him or her' or 'them'.","ex":{"en":"Talk to your baby, play games, and show her how much you enjoy her company.","cn":"和你的宝宝说话，做游戏，让他（她）知道你很喜欢和他（她）在一起。"}},{"pos":"PRON-SING 单数型代词","cn":"（有时指国家或民族）她，它","en":"Her is sometimes used to refer to a country or nation.","ex":{"en":"Our reporter looks at reactions to Britain's apparently deep-rooted distrust of her EU partner.","cn":"英国对其欧盟伙伴显然存在着根深蒂固的不信任，我们的记者就人们对此的反应进行了报道。"}},{"pos":"PRON-SING 单数型代词","cn":"（有时指汽车、机器或船）它","en":"People sometimes use her to refer to a car, machine, or ship.","ex":{"en":"Kemp got out of his car. 'Just fill her up, thanks.'","cn":"肯普下了车。“给它加满油，谢谢。”"}}]},"examples":[{"en":"The manager will be free soon — you can wait for her here.","cn":"经理很快就有空了，你可以在这里等她。"},{"en":"We're going to call her Sophie.","cn":"我们将给她起名索菲。"}]},"held":{"lemma":"hold","media":{"uk":"media/uk/held__gb_1.mp3","us":"media/us/held__us_1.mp3"}},"heading":{"media":{"uk":"media/uk/heading__gb_1.mp3","us":"media/us/heading__us_1.mp3"},"oxford":{"phon":"ˈhedɪŋ","pos":"noun","senses":[{"en":"a title printed at the top of a page or at the beginning of a section of a book","cn":"（页首或章节开头的）标题","ex":{"en":"chapter headings","cn":"篇章标题"}},{"en":"the subject of each section of a speech or piece of writing","cn":"（讲话或作品各章节的）主题","ex":{"en":"The company's aims can be grouped under three main headings.","cn":"公司的目标可分成三大类。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"标题;题目","en":"A heading is the title of a piece of writing, which is written or printed at the top of the page.","ex":{"en":"...helpful chapter headings.","cn":"有用的章节标题"}}]},"examples":[{"en":"The company's aims can be grouped under three main headings.","cn":"公司的目标可分成三大类。"},{"en":"chapter headings","cn":"篇章标题"}],"base":"head"},"he":{"media":{"uk":"media/uk/he__gb_1.mp3","us":"media/us/he__us_1.mp3"},"oxford":{"phon":"hi","pos":"pronoun","senses":[{"en":"a male person or animal that has already been mentioned or is easily identified","cn":"他；它（指雄性动物）","ex":{"en":"Everyone liked my father—he was the perfect gentleman.","cn":"大家都喜欢我父亲，他是真正的绅士。"}},{"en":"a person, male or female, whose sex is not stated or known, especially when referring to somebody mentioned earlier or to a group in general","cn":"人（指性别未说明或不知道的男性或女性，尤指曾提过的人或泛指某群体）","lab":"old-fashioned","ex":{"en":"Every child needs to know that he is loved.","cn":"每个孩子都需要知道自己是有人爱的。"}},{"en":"used when referring to God","cn":"（指上帝）"},{"en":"a male","cn":"雄性","g":"[singular]","lab":"informal","ex":{"en":"What a nice dog—is it a he or a she?","cn":"多好看的狗，它是公的还是母的？"},"pos":"noun"},{"en":"a male animal","cn":"雄性动物","ex":{"en":"a he-goat","cn":"一头公山羊"},"pos":"noun"},{"en":"Her/His Excellency","cn":"阁下","ex":{"en":"HE the Australian Ambassador","cn":"澳大利亚大使阁下"},"pos":"abbreviation"},{"en":"higher education","cn":"高等教育","pos":"abbreviation"}]},"collins":{"senses":[{"pos":"PRON-SING 单数型代词","cn":"他;它（指雄性动物）","en":"You use he to refer to a man, boy, or male animal.","ex":{"en":"He could never quite remember all our names","cn":"他永远也无法记住我们所有人的名字。"}},{"pos":"PRON-SING 单数型代词","cn":"（书面英语中泛指人）他，她（有些人不喜欢这种用法，更倾向于使用 he or she 或 they）","en":"In written English, he is sometimes used to refer to a person without saying whether that person is a man or a woman. Some people dislike this use and prefer to use 'he or she' or 'they'.","ex":{"en":"The teacher should encourage the child to proceed as far as he can, and when he is stuck, ask for help.","cn":"老师应该鼓励孩子尽量自己去做，遇到困难时，寻求帮助。"}},{"pos":"PRON-SING 单数型代词","cn":"(某些宗教中）上帝","en":"In some religions, He is used to refer to God."}]},"examples":[{"en":"HE the Australian Ambassador","cn":"澳大利亚大使阁下"},{"en":"‘Where’s Paul?’ ‘He’s gone to the cinema.’ “","cn":"保罗在哪儿？”“他去看电影了。”"}]},"helper":{"media":{"uk":"media/uk/helper__gb_1.mp3","us":"media/us/helper__us_1.mp3"},"oxford":{"phon":"ˈhelpə(r)","pos":"noun","senses":[{"en":"a person who helps somebody to do something","cn":"帮手；助手","ex":{"en":"He recruited a band of willing helpers.","cn":"他动员了一批自愿帮忙的人。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"帮助者;帮手;助手","en":"A helper is a person who helps another person or group with a job they are doing."}]},"examples":[{"en":"a willing helper","cn":"自愿帮忙者"},{"en":"I was a classroom helper at the local primary school.","cn":"我是当地小学的课室助理。"}]},"heating":{"oxford":{"phon":"ˈhiːtɪŋ","pos":"noun","senses":[{"en":"the process of supplying heat to a room or building; a system used to do this","cn":"供暖；供暖系统；暖气设备","ex":{"en":"to put/turn the heating on","cn":"打开供暖设备"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（尤指从经济角度考虑的）供暖，暖气供应","en":"Heating is the process of heating a building or room, considered especially from the point of view of how much this costs.","ex":{"en":"You can still find cottages for £150 a week, including heating.","cn":"你仍可以找到包括供暖在内每周租金150英镑的度假别墅。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（建筑物的）供暖系统，暖气设备","en":"Heating is the system and equipment that is used to heat a building.","ex":{"en":"There is no heating in the shed, so the dogs would be bitterly cold at night","cn":"小屋里没有供暖设备，所以这些狗夜里会非常冷。"}}]},"media":{"uk":"media/uk/heating__gb_1.mp3","us":"media/us/heating__us_1.mp3"},"examples":[{"en":"Who turned the heating off?","cn":"谁把暖气关掉了？"},{"en":"What type of heating do you have?","cn":"你们用什么供暖？"}],"base":"heat"},"head":{"media":{"uk":"media/uk/head__gb_1.mp3","us":"media/us/head__us_1.mp3"},"oxford":{"phon":"hed","pos":"noun","senses":[{"en":"the part of the body on top of the neck containing the eyes, nose, mouth and brain","cn":"头；头部","g":"[countable]","lab":"informal","sc":"part of body","ex":{"en":"She nodded her head in agreement.","cn":"她点头表示同意。"}},{"en":"the mind or brain","cn":"头脑；脑筋","g":"[countable]","sc":"mind","ex":{"en":"I sometimes wonder what goes on in that head of yours.","cn":"我有时不明白你脑子里在想些什么。"}},{"en":"the size of a person’s or animal’s head, used as a measurement of distance or height","cn":"（人或动物的）一头长，一头高","g":"[singular]","sc":"measurement","ex":{"en":"She's a good head taller than her sister.","cn":"她比妹妹足足高出了一个头。"}},{"en":"a continuous pain in your head","cn":"（持续的）头痛","g":"[countable, usually singular]","lab":"informal","sc":"pain","ex":{"en":"I woke up with a really bad head this morning.","cn":"我今天早晨醒来时头痛得厉害。"}},{"en":"the person in charge of a group of people or an organization","cn":"负责人；领导人","g":"[countable, uncountable]","sc":"of group/organization","ex":{"en":"the heads of government/state","cn":"政府首脑；国家元首"}},{"en":"the person in charge of a school or college","cn":"校长；院长","g":"[countable]","lab":"British English","sc":"of school/college","ex":{"en":"I've been called in to see the Head.","cn":"我接到通知去见校长。"}},{"en":"the side of a coin that has a picture of the head of a person on it, used as one choice when a coin is tossed to decide something","cn":"硬币正面（有人头像）","g":"[uncountable]","sc":"side of coin","ex":{"en":"I called heads and it came down tails.","cn":"我要了正面，可落下来却是反面朝上。"}},{"en":"the end of a long narrow object that is larger or wider than the rest of it","cn":"较宽大的一端；头","g":"[countable, usually singular]","sc":"end of object","ex":{"en":"the head of a nail","cn":"钉子的头"}},{"en":"the top or highest part of something","cn":"顶端；上端","g":"[singular]","sc":"top","ex":{"en":"at the head of the page","cn":"在页眉处"}},{"en":"the place where a river begins","cn":"（河流）源头","g":"[singular]","sc":"of river"},{"en":"the most important seat at a table","cn":"上座（桌子旁最重要的座位）","g":"[singular]","sc":"of table","ex":{"en":"The President sat at the head of the table.","cn":"总统坐在桌子的上首。"}},{"en":"the position at the front of a line of people","cn":"领头位置；排头","g":"[singular]","sc":"of line of people","ex":{"en":"The prince rode at the head of his regiment.","cn":"王子骑马走在卫队的前头。"}},{"en":"the mass of leaves or flowers at the end of a stem","cn":"（茎梗顶端的）叶球，头状花序","g":"[countable]","sc":"of plant","ex":{"en":"Remove the dead heads to encourage new growth.","cn":"把枯萎了的残花除掉以促使新的生长。"}},{"en":"the mass of small bubbles on the top of a glass of beer","cn":"啤酒泡沫；酒头","g":"[singular]","sc":"on beer"},{"en":"the part of a spot on your skin that contains a thick yellow liquid (= pus)","cn":"脓头","g":"[countable]","sc":"of spot"},{"en":"the component of a sound or video recording system that converts data on the disk or tape into digital electronic data (and the other way round)","cn":"（录音或录像设备的）磁头","g":"[countable]","sc":"in recording system"},{"en":"used to say how many animals of a particular type are on a farm, in a herd, etc.","cn":"（表示农场或牧群等的牲畜的数目）头","g":"[plural]","sc":"number of animals","ex":{"en":"200 head of sheep","cn":"200 只绵羊"}},{"en":"the pressure produced by steam in a small space","cn":"蒸汽压力","g":"[singular]","sc":"pressure","ex":{"en":"The old engine still manages to build up a good head of steam.","cn":"旧发动机仍然能够产生良好的蒸汽头。"}},{"en":"oral sex (= using the mouth to give somebody sexual pleasure)","cn":"口交","g":"[uncountable]","lab":"taboo, slang，，","sc":"sex","ex":{"en":"to give head","cn":"进行口交"}},{"en":"the central part of a phrase, which has the same grammatical function as the whole phrase. In the phrase ‘the tall man in a suit’, man is the head.","cn":"（短语的）中心成分，中心词，主导词","g":"[countable]","sc":"linguistics"},{"en":"(in nouns) a person who is very enthusiastic about a particular thing or is addicted to a particular drug","cn":"（构成名词）⋯迷，⋯瘾君子","ex":{"en":"a gearhead","cn":"技术设备发烧友"},"pos":"suffix"},{"en":"to move in a particular direction","cn":"前往","g":"[intransitive]","lab":"figurative","sc":"move towards","ex":{"en":"Where are we heading?","cn":"我们要往哪儿去？"},"pos":"verb"},{"en":"to lead or be in charge of something","cn":"领导；主管","g":"[transitive]","sc":"group/organization","ex":{"en":"She has been appointed to head the research team.","cn":"她受命领导研究小组。"},"pos":"verb"},{"en":"to be at the top of a list of names or at the front of a line of people","cn":"位于排行之首；排在前头","g":"[transitive]","sc":"list/line of people","ex":{"en":"Italy heads the table after two games.","cn":"两场比赛之后意大利队排名榜首。"},"pos":"verb"},{"en":"to put a word or words at the top of a page or section of a book as a title","cn":"在（页或篇章的）顶端加标题","g":"[transitive, usually passive]","sc":"be at top","ex":{"en":"The chapter was headed ‘My Early Life’.","cn":"这一章的标题是“我的早年生活”。"},"pos":"verb"},{"en":"to hit a football with your head","cn":"用头顶（球）","g":"[transitive]","sc":"football","ex":{"en":"Walsh headed the ball into an empty goal.","cn":"沃尔什把球顶进了空门。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（人的）头，头部","en":"Your head is the top part of your body, which has your eyes, mouth, and brain in it.","ex":{"en":"She turned her head away from him","cn":"她把头别过去，不再看他。"}},{"pos":"N-COUNT 可数名词","cn":"头脑;心智;才智","en":"You can use head to refer to your mind and your mental abilities.","ex":{"en":"I can't get that song out of my head.","cn":"那首歌在我脑海中挥之不去。"}},{"pos":"N-SING 单数名词","cn":"（队伍中的）领头位置;队首;排头","en":"The head of a line of people or vehicles is the front of it, or the first person or vehicle in the line.","ex":{"en":"...the head of the queue","cn":"队首"}},{"pos":"VERB 动词","cn":"排在（队列等）的最前面","en":"If someone or something heads a line or procession, they are at the front of it.","ex":{"en":"The parson, heading the procession, had just turned right towards the churchyard.","cn":"走在行进队伍最前面的教区牧师刚刚向右转弯，朝着教堂墓地走去。"}},{"pos":"VERB 动词","cn":"居…之首;在…名列首位","en":"If something heads a list or group, it is at the top of it.","ex":{"en":"Running a business heads the list of ambitions among the 1,000 people interviewed by Good Housekeeping magazine.","cn":"在《好管家》杂志采访过的1,000人中，创立自己的公司在理想抱负中列在首位。"}},{"pos":"N-SING 单数名词","cn":"顶部;上端","en":"The head of something is the highest or top part of it.","ex":{"en":"...the head of the stairs","cn":"楼梯的顶部"}},{"pos":"N-COUNT 可数名词","cn":"（细长物体的）头部，顶端","en":"The head of something long and thin is the end which is wider than or a different shape from the rest, and which is often considered to be the most important part.","ex":{"en":"There should be no exposed screw heads","cn":"螺钉顶端不应该外露。"}},{"pos":"N-COUNT 可数名词","cn":"（中小学的）校长","en":"The head of a school is the teacher who is in charge.","ex":{"en":"She is full of admiration for the head and teachers.","cn":"她对校长和教师们满心钦佩。"}},{"pos":"N-COUNT 可数名词","cn":"（公司、组织的）负责人，领导人，首脑，长，主任","en":"The head of a company or organization is the person in charge of it and in charge of the people in it.","ex":{"en":"Heads of government from more than 100 countries gather in Geneva tomorrow.","cn":"来自100多个国家的政府首脑明日将齐聚日内瓦。"}},{"pos":"VERB 动词","cn":"掌管;主管;负责","en":"If you head a department, company, or organization, you are the person in charge of it.","ex":{"en":"...Michael Williams, who heads the department's Office of Civil Rights.","cn":"负责该部民权处的迈克尔·威廉斯"}},{"pos":"N-COUNT 可数名词","cn":"脓头","en":"The head of an infected spot is its white or yellow centre."},{"pos":"N-COUNT 可数名词","cn":"（啤酒表层的）泡沫;酒头","en":"The head on a glass of beer is the layer of small bubbles that form on the top of the beer."},{"pos":"N-PLURAL 复数名词","cn":"（表示牲畜的数目）头","en":"You can use head to say how many animals of a particular type a farmer has. For example, if they have fifty head of cattle, they have fifty cows."},{"pos":"N-COUNT 可数名词","cn":"头痛","en":"If you have a bad head, you have a headache.","ex":{"en":"I had a terrible head and was extraordinarily drunk.","cn":"我头很痛，已经酩酊大醉。"}},{"pos":"ADV 副词","cn":"（硬币的）有人头像的一面，正面","en":"If you toss a coin and it comes down heads, you can see the side of the coin which has a picture of a head on it.","ex":{"en":"'We might toss up for it,' suggested Ted. 'If it's heads, then we'll talk.'","cn":"“我们可以掷硬币来决定。”特德建议道，“如果是正面，我们就谈谈。”"}},{"pos":"VERB 动词","cn":"朝着（某一地点）行进（美国英语中亦作 are headed）","en":"If you are heading for a particular place, you are going towards that place. In American English, you can also say that you are headed for a particular place.","ex":{"en":"He headed for the bus stop","cn":"他朝着公共汽车站走去。"}},{"pos":"VERB 动词","cn":"很可能要遭受，会招致（美国英语中亦作 is headed for）","en":"If something or someone is heading for a particular result, the situation they are in is developing in a way that makes that result very likely. In American English, you can also say that something or someone is headed for a particular result.","ex":{"en":"The latest talks aimed at ending the civil war appear to be heading for deadlock","cn":"为结束内战而进行的最新谈判好像要陷入僵局。"}},{"pos":"VERB 动词","cn":"标题为","en":"If a piece of writing is headed a particular title, it has that title written at the beginning of it.","ex":{"en":"One chapter is headed, 'Beating the Test'.","cn":"有一章的标题为“战胜考试”。"}},{"pos":"VERB 动词","cn":"（足球比赛中）用头顶（球）","en":"If you head a ball in football, you hit it with your head in order to make it go in a particular direction.","ex":{"en":"He headed the ball across the face of the goal.","cn":"他一个头球，球从球门前横飞而过。"}},{"pos":"PHRASE 短语","cn":"每人/人均","en":"You use a head or per head after stating a cost or amount in order to indicate that that cost or amount is for each person in a particular group.","ex":{"en":"This simple chicken dish costs less than £1 a head","cn":"这道简单的鸡肉菜肴每人的花费还不到1英镑。"}},{"pos":"PHRASE 短语","cn":"让人生气;让人沮丧","en":"If something or someone does your head in, they make you angry or frustrated.","ex":{"en":"Living with my parents is doing my head in.","cn":"和父母住在一起让我很沮丧。"}},{"pos":"PHRASE 短语","cn":"从头到脚;全身","en":"From head to foot means all over your body.","ex":{"en":"Colin had been put into a bath and been scrubbed from head to foot.","cn":"科林被放进浴缸，从头到脚仔仔细细洗了个干净。"}},{"pos":"PHRASE 短语","cn":"擅长","en":"If you have a head for something, you can deal with it easily. For example, if you have a head for figures, you can do arithmetic easily, and if you have a head for heights, you can climb to a great height without feeling afraid.","ex":{"en":"I don't have a head for business.","cn":"我没有生意头脑。"}},{"pos":"PHRASE 短语","cn":"充分理解并接受;打定（主意）","en":"If you get a fact or idea into your head, you suddenly realize or think that it is true and you usually do not change your opinion about it.","ex":{"en":"Once they get an idea into their heads, they never give up.","cn":"一旦接受了一个想法，他们就永远不会放弃。"}},{"pos":"PHRASE 短语","cn":"终于明白","en":"If you say that someone has got something into their head, you mean that they have finally understood or accepted it, and you are usually criticizing them because it has taken them a long time to do this.","ex":{"en":"Managers have at last got it into their heads that they can no longer accept inefficient operations.","cn":"管理者们终于意识到自己不能再安于低效率的运营了。"}},{"pos":"PHRASE 短语","cn":"让…自由行动;对…不加约束","en":"If you give someone their head, you allow them to do what they want to do, without trying to advise or stop them.","ex":{"en":"He recognised ability and gave people their heads.","cn":"他发现别人的才能，并且让他们自由发挥。"}},{"pos":"PHRASE 短语","cn":"（酒）使人感到醉，上头","en":"If alcoholic drink goes to your head, it makes you feel drunk.","ex":{"en":"That wine was strong, it went to your head.","cn":"那酒劲儿很大，喝了会上头。"}},{"pos":"PHRASE 短语","cn":"（赞扬或成功）冲昏…的头脑，使…骄傲自满","en":"If you say that something such as praise or success goes to someone's head, you are criticizing them because you think that it makes them too proud or confident.","ex":{"en":"Ford is definitely not a man to let a little success go to his head.","cn":"福特绝对不是那种会被一点点成功冲昏头脑的人。"}},{"pos":"PHRASE 短语","cn":"深陷情网","en":"If you are head over heels or head over heels in love, you are very much in love.","ex":{"en":"I was very attracted to men and fell head over heels many times.","cn":"我很容易被男性吸引，曾多次深陷情网。"}},{"pos":"PHRASE 短语","cn":"保持镇静/张皇失措","en":"If you keep your head, you remain calm in a difficult situation. If you lose your head, you panic or do not remain calm in a difficult situation.","ex":{"en":"She was able to keep her head and not panic","cn":"她设法保持镇静，没有陷入恐慌。"}},{"pos":"PHRASE 短语","cn":"停止;结束","en":"If you knock something on the head, you stop it.","ex":{"en":"When we stop enjoying ourselves we'll knock it on the head.","cn":"等玩够了，我们就会结束。"}},{"pos":"PHRASE 短语","cn":"（表示强调）大笑/大声尖叫","en":"Phrases such as laugh your head off and scream your head off can be used to emphasize that someone is laughing or screaming a lot or very loudly.","ex":{"en":"He carried on telling a joke, laughing his head off.","cn":"他继续讲笑话，自己笑得前仰后合。"}},{"pos":"PHRASE 短语","cn":"（吸毒后）昏头昏脑的，神志不清的","en":"If you say that someone is off their head, you mean that they have taken so many drugs that they do not know what they are doing."},{"pos":"PHRASE 短语","cn":"昏了头的;愚蠢的","en":"If you say that someone is off their head, you think that their ideas or behaviour are very strange, foolish, or dangerous.","ex":{"en":"He's gone completely off his head.","cn":"他已经完全昏了头了。"}},{"pos":"PHRASE 短语","cn":"倒过来想;从全新的角度理解","en":"If you stand an idea or argument on its head or turn it on its head, you think about it or treat it in a completely new and different way.","ex":{"en":"Their relationship turned the standard notion of marriage on its head.","cn":"他们的关系完全颠覆了传统的婚姻观念。"}},{"pos":"PHRASE 短语","cn":"超过…的理解力","en":"If something such as an idea, joke, or comment goes over someone's head, it is too difficult for them to understand.","ex":{"en":"I admit that a lot of the ideas went way over my head.","cn":"我承认那些想法中有很多远远超出了我的理解力。"}},{"pos":"PHRASE 短语","cn":"未与…商量地;(尤指)越级","en":"If someone does something over another person's head, they do it without asking them or discussing it with them, especially when they should do so because the other person is in a position of authority.","ex":{"en":"He was reprimanded for trying to go over the heads of senior officers.","cn":"他因试图越过高层官员自作主张而受到斥责。"}},{"pos":"PHRASE 短语","cn":"（不好的事情）再次出现，重新抬头","en":"If you say that something unpleasant or embarrassing rears its ugly head or raises its ugly head, you mean that it occurs, often after not occurring for some time.","ex":{"en":"There was a problem which reared its ugly head about a week after she moved back in","cn":"她搬回来大约一周之后，一个问题又重新出现了。"}},{"pos":"PHRASE 短语","cn":"倒立;竖蜻蜓","en":"If you stand on your head, you balance upside down with the top of your head and your hands on the ground."},{"pos":"PHRASE 短语","cn":"理解;弄明白","en":"If you say that you cannot make head nor tail of something or you cannot make head or tail of it, you are emphasizing that you cannot understand it at all.","ex":{"en":"I couldn't make head nor tail of the damn film.","cn":"这部该死的影片我一点儿都看不懂。"}},{"pos":"PHRASE 短语","cn":"突然决定（做某事，尤指古怪或愚蠢的事）；心血来潮","en":"If somebody takes it into their head to do something, especially something strange or foolish, they suddenly decide to do it.","ex":{"en":"He suddenly took it into his head to go out to Australia to stay with his son.","cn":"他突然心血来潮，打算去澳大利亚和儿子一起住。"}},{"pos":"PHRASE 短语","cn":"到了危急关头;到达关键点","en":"If a problem or disagreement comes to a head or is brought to a head, it becomes so bad that something must be done about it.","ex":{"en":"These problems came to a head in September when five of the station's journalists were sacked.","cn":"这些问题在9月变得十分尖锐，当时该台有5名记者遭到辞退。"}},{"pos":"PHRASE 短语","cn":"严厉训斥","en":"If you bang peoples' heads together or knock their heads together, you tell them off severely for doing something wrong or for not doing something they were asked to do.","ex":{"en":"It is now high time he banged his colleagues' heads together.","cn":"现在该是他敲打敲打同事们的时候了。"}},{"pos":"PHRASE 短语","cn":"集体商讨;集思广益","en":"If two or more people put their heads together, they talk about a problem they have and try to solve it.","ex":{"en":"So everyone put their heads together and eventually an amicable arrangement was reached.","cn":"因此大家集思广益，最终作出了妥善的安排。"}},{"pos":"PHRASE 短语","cn":"（尤指在生意方面）勉强逃脱困境","en":"If you keep your head above water, you just avoid getting into difficulties; used especially to talk about business.","ex":{"en":"We are keeping our head above water, but our cash flow position is not too good.","cn":"我们正努力避免陷入困境，但我们的现金流动情况不太好。"}},{"pos":"PHRASE 短语","cn":"有人会遭殃，有人会（因此）受到惩罚（尤指被解雇）","en":"If you say that heads will roll as a result of something bad that has happened, you mean that people will be punished for it, especially by losing their jobs.","ex":{"en":"The group's problems have led to speculation that heads will roll.","cn":"已经有人猜测，该集团的问题会导致一些人被解雇。"}},{"pos":"","cn":"","en":"相关词组：head off head up"}]},"examples":[{"en":"For some reason, she's got it into her head (= believes) that the others don't like her.","cn":"由于某种原因，她有一种感觉，认为其他人都不喜欢她。"},{"en":"The favourite won by a short head (= a distance slightly less than the length of a horse's head).","cn":"最被看好的那匹马以不足一马头之差的优势获胜。"}]},"hearth":{"media":{"uk":"media/uk/hearth__gb_1.mp3","us":"media/us/hearth__us_1.mp3"},"oxford":{"phon":"hɑːθ","pos":"noun","senses":[{"en":"the floor at the bottom of a fireplace (= the space for a fire in the wall of a room); the area in front of this","cn":"壁炉炉床；壁炉前的地面","ex":{"en":"A log fire roared in the open hearth.","cn":"柴火在敞开着的壁炉里熊熊燃烧。"}},{"en":"home and family life","cn":"家和家庭生活","lab":"literary","ex":{"en":"a longing for hearth and home","cn":"对温暖家庭的渴望"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"壁炉地面;壁炉炉床","en":"The hearth is the floor of a fireplace, which sometimes extends into the room.","ex":{"en":"It was winter and there was a huge fire roaring in the hearth.","cn":"时值冬天，壁炉里炉火熊熊。"}},{"pos":"PHRASE 短语","cn":"温暖舒适的家庭生活","en":"A person's home and family life can be referred to as their hearth and home .","ex":{"en":"...a man who leaves his hearth and home to labour as a miner in the inhospitable north.","cn":"离开温暖舒适的家到荒凉的北方做矿工的男子"}}]},"examples":[{"en":"The cat dozed in its favourite spot on the hearth.","cn":"猫躺在壁炉前它最喜欢的地方打盹。"},{"en":"A log fire roared in the open hearth.","cn":"柴火在敞开着的壁炉里熊熊燃烧。"}]},"heart":{"media":{"uk":"media/uk/heart__gb_1.mp3","us":"media/us/heart__us_1.mp3"},"oxford":{"phon":"hɑːt","pos":"noun","senses":[{"en":"the organ in the chest that sends blood around the body, usually on the left in humans","cn":"心；心脏","g":"[countable]","sc":"part of body","ex":{"en":"The patient's heart stopped beating for a few seconds.","cn":"病人的心跳停顿了几秒钟。"}},{"en":"the outside part of the chest where the heart is","cn":"胸部心脏的部位；胸怀","g":"[countable]","lab":"literary","sc":"part of body","ex":{"en":"She clasped the photo to her heart.","cn":"她把相片紧紧地抱在怀里。"}},{"en":"a thing that is like a heart in shape, often red and used as a symbol of love; a symbol like a heart used to mean the verb ‘love’","cn":"心形物；（常指象征爱的）红心；心形（表示动词“爱”）","g":"[countable]","sc":"shape","ex":{"en":"The words ‘I love you’ were written inside a big red heart.","cn":"“我爱你”这几个字写在一个大红心里。"}},{"en":"the place in a person where the feelings and emotions are thought to be, especially those connected with love","cn":"内心；心肠；（尤指）爱心","g":"[countable]","sc":"feelings/emotions","ex":{"en":"She has a kind heart.","cn":"她有一颗善良的心。"}},{"en":"having the type of character or personality mentioned","cn":"有…性格（或品格）的","sc":"-hearted","ex":{"en":"simple-hearted","cn":"心地单纯"}},{"en":"the most important part of something","cn":"核心；实质；要点","g":"[singular]","sc":"important part","ex":{"en":"the heart of the matter/problem","cn":"事情／问题的核心"}},{"en":"the part that is in the centre of something","cn":"中心；中央","g":"[countable, usually singular]","sc":"centre","ex":{"en":"a quiet hotel in the very heart of the city","cn":"一家位于市中心的安静的旅馆"}},{"en":"the smaller leaves in the middle of a cabbage, lettuce, etc.","cn":"菜心","g":"[countable]","sc":"of vegetable"},{"en":"one of the four suits (= sets) in a pack of cards, with red heart symbols on them","cn":"（扑克牌的）红桃，红心","g":"[plural, uncountable]","sc":"in card games","ex":{"en":"the queen of hearts","cn":"红桃王后"}},{"en":"one card from the suit called hearts","cn":"（一张）红桃，红心","g":"[countable]","sc":"in card games","ex":{"en":"Who played that heart?","cn":"谁打出那张红桃？"}},{"en":"to like somebody/something very much; to love somebody/something","cn":"非常喜欢；爱","ex":{"en":"She wore an ‘I heart Dad’ T-shirt.","cn":"她穿了一件写着“我爱爸爸”的 T 恤衫。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"心;心脏;胸口","en":"Your heart is the organ in your chest that pumps the blood around your body. People also use heart to refer to the area of their chest that is closest to their heart.","ex":{"en":"The bullet had passed less than an inch from Andrea's heart","cn":"子弹在离安德烈亚的心脏不到一英寸的地方穿过。"}},{"pos":"N-COUNT 可数名词","cn":"内心;心灵;心情","en":"You can refer to someone's heart when you are talking about their deep feelings and beliefs.","ex":{"en":"Alik's words filled her heart with pride","cn":"亚利克的话让她心感自豪。"}},{"pos":"N-VAR 可变名词","cn":"心肠;心地;同情心","en":"You use heart when you are talking about someone's character and attitude towards other people, especially when they are kind and generous.","ex":{"en":"She loved his brilliance and his generous heart","cn":"她深爱他的才华横溢和古道热肠。"}},{"pos":"N-SING 单数名词","cn":"爱情;爱恋;感情","en":"If you refer to things of the heart, you mean love and relationships.","ex":{"en":"This is an excellent time for affairs of the heart.","cn":"这是谈情说爱的绝佳时机。"}},{"pos":"N-SING 单数名词","cn":"核心;实质;重点;要点","en":"The heart of something is the most central and important part of it.","ex":{"en":"The heart of the problem is supply and demand","cn":"问题的核心是供求关系。"}},{"pos":"N-SING 单数名词","cn":"（地方的）中心","en":"The heart of a place is its centre.","ex":{"en":"...a busy dentists' practice in the heart of London's West End.","cn":"位于伦敦西区中心的一个繁忙的牙科诊所"}},{"pos":"N-COUNT 可数名词","cn":"（蔬菜的）菜心","en":"The heart of a lettuce, cabbage, or other vegetable is its centre leaves."},{"pos":"N-COUNT 可数名词","cn":"（作为爱的象征的）心形","en":"A heart is a shape that is used as a symbol of love: ♥.","ex":{"en":"...heart-shaped chocolates.","cn":"心形巧克力"}},{"pos":"N-UNCOUNT-COLL 不可数集合名词","cn":"（纸牌的）红桃，红心","en":"Hearts is one of the four suits in a pack of playing cards. Each card in the suit is marked with one or more red symbols in the shape of a heart.","ex":{"en":"West had to decide whether to play a heart.","cn":"韦斯特必须决定是否要出一张红桃。"}},{"pos":"PHRASE 短语","cn":"全心全意地;真心实意地","en":"If you feel or believe something with all your heart, you feel or believe it very strongly.","ex":{"en":"My own family I loved with all my heart.","cn":"我真心实意地爱我全家人。"}},{"pos":"PHRASE 短语","cn":"（人）本质上，实际上，内心里","en":"If you say that someone is a particular kind of person at heart, you mean that that is what they are really like, even though they may seem very different.","ex":{"en":"He was a very gentle boy at heart.","cn":"他实际上是个非常温柔的男生。"}},{"pos":"PHRASE 短语","cn":"十分关心（某人的利益或福祉）","en":"If you say that someone has your interests or your welfare at heart, you mean that they are concerned about you and that is why they are doing something.","ex":{"en":"She told him she only had his interests at heart.","cn":"她告诉他自己万事都是为了他好。"}},{"pos":"PHRASE 短语","cn":"（通常指因感情破裂而）使…伤心，使…心碎","en":"If someone breaks your heart, they make you very sad and unhappy, usually because they end a love affair or close relationship with you."},{"pos":"PHRASE 短语","cn":"（尤指因对他人的苦难无能为力而）使…伤心，使…心碎","en":"If something breaks your heart, it makes you feel very sad and depressed, especially because people are suffering but you can do nothing to help them.","ex":{"en":"It really breaks my heart to see them this way.","cn":"看到他们这个样子可真让我伤心。"}},{"pos":"PHRASE 短语","cn":"心碎;伤心","en":"If you say that someone has a broken heart, you mean that they are very sad, for example because a love affair has ended unhappily.","ex":{"en":"She never recovered from her broken heart.","cn":"她心上的伤再也没能愈合。"}},{"pos":"PHRASE 短语","cn":"背得出;靠记忆","en":"If you know something such as a poem by heart, you have learned it so well that you can remember it without having to read it.","ex":{"en":"Mack knew this passage by heart.","cn":"麦克会背这一段。"}},{"pos":"PHRASE 短语","cn":"态度的转变","en":"If someone has a change of heart, their attitude towards something changes.","ex":{"en":"Several brokers have had a change of heart about prospects for the company","cn":"几位经纪人对该公司前景的看法已经有所改变。"}},{"pos":"PHRASE 短语","cn":"为…所重视（或关注）","en":"If something such as a subject or project is close to your heart or near to your heart, it is very important to you and you are very interested in it and concerned about it.","ex":{"en":"Animal welfare is a subject very close to my heart.","cn":"动物福利是我非常关注的一个问题。"}},{"pos":"PHRASE 短语","cn":"尽情地;痛痛快快地","en":"If you can do something to your heart's content, you can do it as much as you want.","ex":{"en":"I was delighted to be able to eat my favorite dishes to my heart's content.","cn":"我很高兴能够痛痛快快地吃我最喜爱的菜。"}},{"pos":"CONVENTION 惯用语","cn":"我发誓（所说的是真的）/你敢发誓（所说的是真的）吗？","en":"You can say 'cross my heart' when you want someone to believe that you are telling the truth. You can also ask 'cross your heart?', when you are asking someone if they are really telling the truth.","ex":{"en":"And I won't tell any of the other girls anything you tell me about it. I promise, cross my heart.","cn":"我不会把你告诉我的事告诉任何其他女孩。我发誓，保证不会。"}},{"pos":"PHRASE 短语","cn":"真诚地;发自内心地","en":"If you say something from the heart or from the bottom of your heart, you sincerely mean what you say.","ex":{"en":"He spoke with confidence, from the heart","cn":"他的话充满信心，发自心坎。"}},{"pos":"PHRASE 短语","cn":"鼓励…;使…振作起来","en":"If something gives you heart, it makes you feel more confident or happy about something.","ex":{"en":"It gave me heart to see one thug get what he deserves.","cn":"看到一个恶棍罪有应得真是大快我心。"}},{"pos":"PHRASE 短语","cn":"不忍心（做…）","en":"If you want to do something but do not have the heart to do it, you do not do it because you know it will make someone unhappy or disappointed.","ex":{"en":"We knew all along but didn'thave the heart to tell her.","cn":"我们一直都知道，但却不忍心告诉她。"}},{"pos":"PHRASE 短语","cn":"在心底里;在内心深处","en":"If you believe or know something in your heart of hearts, that is what you really believe or think, even though it may sometimes seem that you do not.","ex":{"en":"I know in my heart of hearts that I am the right man for that mission.","cn":"我心里深知我是完成那项任务的合适人选。"}},{"pos":"PHRASE 短语","cn":"对…无兴趣;心不在…上","en":"If your heart isn't in the thing you are doing, you have very little enthusiasm for it, usually because you are depressed or are thinking about something else.","ex":{"en":"I tried to learn some lines but my heart wasn't really in it.","cn":"我想要背几句台词，但我的心根本不在那上面。"}},{"pos":"PHRASE 短语","cn":"失去信心;灰心;泄气","en":"If you lose heart, you become sad and depressed and are no longer interested in something, especially because it is not progressing as you would like.","ex":{"en":"He appealed to his countrymen not to lose heart.","cn":"他呼吁自己的同胞不要丧失信心。"}},{"pos":"PHRASE 短语","cn":"爱上…；对…倾心","en":"If you lose your heart to someone, you fall in love with them."},{"pos":"PHRASE 短语","cn":"激动非常;焦急万分;害怕得要命","en":"If your heart is in your mouth, you feel very excited, worried, or frightened.","ex":{"en":"My heart was in my mouth when I walked into her office.","cn":"我走进她的办公室时，紧张得心都到了喉咙口。"}},{"pos":"PHRASE 短语","cn":"敞开心扉;倾吐心里话","en":"If you open your heart or pour out your heart to someone, you tell them your most private thoughts and feelings.","ex":{"en":"She opened her heart to millions yesterday and told how she came close to suicide.","cn":"她昨天在数成百万人面前倾吐心声，讲述了自己是如何差点轻生的。"}},{"pos":"PHRASE 短语","cn":"（尽管有其他缺点但）心地善良，心眼儿好","en":"If you say that someone's heart is in the right place, you mean that they are kind, considerate, and generous, although you may disapprove of other aspects of their character.","ex":{"en":"He is a bit of a tearaway but his heart is in the right place.","cn":"他是有点像个阿飞，但心眼儿不错。"}},{"pos":"PHRASE 短语","cn":"一心想要得到;一心想要做","en":"If you have set your heart on something, you want it very much or want to do it very much.","ex":{"en":"He had always set his heart on a career in the fine arts.","cn":"他一直以来都一心想把美术作为自己的事业。"}},{"pos":"PHRASE 短语","cn":"感情外露;心直口快","en":"If you wear your heart on your sleeve, you openly show your feelings or emotions rather than keeping them hidden."},{"pos":"PHRASE 短语","cn":"全心全意地;尽心尽力地","en":"If you put your heart and soul into something, you do it with a great deal of enthusiasm and energy.","ex":{"en":"He will always be successful when he puts his mind to something, because he puts his heart and soul into it.","cn":"当他专心想干某件事时，他总是能成功，因为他会全心全意地投入其中。"}},{"pos":"PHRASE 短语","cn":"（从…）得到鼓舞;（因…）振作精神","en":"If you take heart from something, you are encouraged and made to feel optimistic by it."},{"pos":"PHRASE 短语","cn":"对…耿耿于怀;为…感到不快","en":"If you take something to heart, for example someone's behaviour, you are deeply affected and upset by it.","ex":{"en":"If someone says something critical I take it to heart.","cn":"如果有人提出批评，我会十分介意。"}}]},"examples":[{"en":"My heart sank when I saw how much work there was left.","cn":"我看到还有那么多活没干时，心顿时沉了下去。"},{"en":"The story captured the hearts and minds of a generation.","cn":"这部小说准确地传达了一代人的感情和思想。"}]},"helplessly":{"oxford":{"phon":"ˈhelpləsli","pos":"adverb","senses":[{"en":"in a way that shows that you are unable to do anything in a particular situation","cn":"无助：以某种方式表明您无法在特定情况下执行任何操作","ex":{"en":"They watched helplessly as their home went up in flames.","cn":"他们无助地看着自己的房子被大火吞噬。"}},{"en":"in a way that shows that you are unable to control a strong feeling","cn":"无法抑制的","ex":{"en":"Both sisters started to laugh helplessly.","cn":"姐妹俩都无奈地笑起来。"}}]},"media":{"uk":"media/uk/helplessly__gb_1.mp3","us":"media/us/helplessly__us_1.mp3"},"examples":[{"en":"They watched helplessly as their home went up in flames.","cn":"他们无奈地看着自己的家被大火吞没。"},{"en":"He began to feel depressed and helpless.","cn":""}]},"height":{"media":{"uk":"media/uk/height__gb_1.mp3","us":"media/us/height__us_1.mp3"},"oxford":{"phon":"haɪt","pos":"noun","senses":[{"en":"the measurement of how tall a person or thing is","cn":"（人或物的）身高，高度","g":"[uncountable, countable]","sc":"measurement","ex":{"en":"Height: 210 mm. Width: 57 mm. Length: 170 mm.","cn":"高：210 毫米；宽：57 毫米；长：170 毫米。"}},{"en":"the quality of being tall or high","cn":"高","g":"[uncountable]","sc":"being tall","ex":{"en":"The height of the mountain did not discourage them.","cn":"山高并没有使他们泄气。"}},{"en":"a particular distance above the ground","cn":"高度","g":"[countable, uncountable]","sc":"distance above ground","ex":{"en":"The aircraft was gaining height.","cn":"飞机在爬高。"}},{"en":"a high place or position","cn":"高地；高处；高位","g":"[countable, usually plural]","sc":"high place","ex":{"en":"Brooklyn Heights","cn":"布鲁克林高地"}},{"en":"the point when something is at its strongest or best","cn":"最强点；最佳点；顶点","g":"[singular]","sc":"strongest point/level","ex":{"en":"The fire reached its height around 2 a.m.","cn":"大火在半夜两点钟左右烧得最猛。"}},{"en":"a better or greater level of something; a situation where something is very good","cn":"更好；更高水平；极佳状况","g":"[plural]","sc":"strongest point/level","ex":{"en":"Their success had reached new heights.","cn":"他们的成就达到新高水平。"}},{"en":"an extreme example of a particular quality","cn":"极端；极度","g":"[singular]","sc":"extreme example","ex":{"en":"It would be the height of folly (= very stupid) to change course now.","cn":"现在改变方向可谓愚蠢至极。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"（从底到顶的）身高;高度","en":"The height of a person or thing is their size or length from the bottom to the top.","ex":{"en":"Her weight is about normal for her height","cn":"按她的身高，她的体重基本正常。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"高","en":"Height is the quality of being tall.","ex":{"en":"She admits that her height is intimidating for some men.","cn":"她承认自己的高个头会令有些男人却步。"}},{"pos":"N-VAR 可变名词","cn":"（距离地面或他物的某一）高度","en":"A particular height is the distance that something is above the ground or above something else mentioned.","ex":{"en":"At the speed and height at which he was moving, he was never more than half a second from disaster.","cn":"以这样的速度在这么高的地方移动，他离灾难始终只有半步之遥。"}},{"pos":"N-COUNT 可数名词","cn":"高处;高地","en":"A height is a high position or place above the ground.","ex":{"en":"From a height, it looks like a desert","cn":"从高处看，它像一片沙漠。"}},{"pos":"N-SING 单数名词","cn":"处于顶峰;处于高潮","en":"When an activity, situation, or organization is at its height, it is at its most successful, powerful, or intense.","ex":{"en":"During the early sixth century emigration from Britain to Brittany was at its height","cn":"6世纪初，从不列颠涌向布列塔尼的移民潮达到了高峰。"}},{"pos":"N-SING 单数名词","cn":"（某一特性）的极致","en":"If you say that something is the height of a particular quality, you are emphasizing that it has that quality to the greatest degree possible.","ex":{"en":"The hip-hugging black and white polka-dot dress was the height of fashion","cn":"黑白圆点花纹的紧身连衣裙当时是最时尚的。"}},{"pos":"N-PLURAL 复数名词","cn":"极度;极点","en":"If something reaches great heights, it becomes very extreme or intense.","ex":{"en":"...the mid-1980s, when house prices rose to absurd heights","cn":"房价高得离谱的20世纪80年代中期"}}]},"examples":[{"en":"Height: 210 mm. Width: 57 mm. Length: 170 mm.","cn":"高：210 毫米；宽：57 毫米；长：170 毫米。"},{"en":"We looked out over the city from the heights of Edinburgh Castle.","cn":"我们从爱丁堡城堡所在的高处俯视整个城市。"}]},"hearing":{"oxford":{"phon":"ˈhɪərɪŋ","pos":"noun","senses":[{"en":"the ability to hear","cn":"听力；听觉","g":"[uncountable]","ex":{"en":"Her hearing is poor.","cn":"她的听觉不灵。"}},{"en":"an official meeting at which the facts about a crime, complaint, etc. are presented to the person or group of people who will have to decide what action to take","cn":"审讯；审理；听审；听证会","g":"[countable]","lab":"especially North American English","ex":{"en":"a court/disciplinary hearing","cn":"庭审；纪律聆讯"}},{"en":"an opportunity to explain your actions, ideas or opinions","cn":"（行为、思想或意见的）解释机会，申辩机会","g":"[singular]","ex":{"en":"to get/give somebody a fair hearing","cn":"得到／给予某人公正的申辩机会"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"听觉;听力","en":"A person's or animal's hearing is the sense which makes it possible for them to be aware of sounds.","ex":{"en":"His mind still seemed clear and his hearing was excellent.","cn":"他的头脑似乎还清楚，听觉也很好。"}},{"pos":"N-COUNT 可数名词","cn":"听证会;听审;聆讯","en":"A hearing is an official meeting which is held in order to collect facts about an incident or problem.","ex":{"en":"The judge adjourned the hearing until next Tuesday.","cn":"法官宣布休庭至下周二再审。"}},{"pos":"PHRASE 短语","cn":"发表意见的机会","en":"If someone gives you a fair hearing or a hearing, they listen to you when you give your opinion about something.","ex":{"en":"Weber gave a fair hearing to anyone who held a different opinion.","cn":"韦伯让持不同意见的人都能有机会发表意见。"}},{"pos":"PHRASE 短语","cn":"在…听力所及的范围内","en":"If someone says something in your hearing or within your hearing, you can hear what they say because they are with you or near you.","ex":{"en":"No one spoke disparagingly of her father in her hearing.","cn":"没有人在她跟前说过她父亲的坏话。"}}]},"media":{"uk":"media/uk/hearing__gb_1.mp3","us":"media/us/hearing__us_1.mp3"},"examples":[{"en":"His views may be unfashionable but he deserves a hearing.","cn":"他的观点可能不合潮流，但应该给他机会解释。"},{"en":"to get/give sb a fair hearing","cn":"得到/给予某人公正的申辩机会"}],"base":"hear"},"hero":{"media":{"uk":"media/uk/hero__gb_1.mp3","us":"media/us/hero__us_1.mp3"},"oxford":{"phon":"ˈhɪərəʊ","pos":"noun","senses":[{"en":"a person who is admired by many people for doing something brave or good","cn":"英雄；豪杰","ex":{"en":"a war hero (= somebody who was very brave during a war)","cn":"战斗英雄"}},{"en":"the main male character in a story, novel, film, etc.","cn":"（故事、小说、电影等的）男主人公，男主角","ex":{"en":"The hero of the novel is a ten-year old boy.","cn":"这部小说的主人公是个十岁的男孩。"}},{"en":"a person that you admire because of a particular quality or skill that they have","cn":"崇拜的对象；偶像","ex":{"en":"my childhood hero","cn":"我孩提时的偶像"}},{"en":"a long bread roll split open along its length and filled with various types of food","cn":"潜艇三明治，长卷三明治（用长卷面包纵向切开，内夹各种食物）","lab":"all North American English"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（书、戏剧、电影或故事中品行端正的）男主角，男主人公","en":"The hero of a book, play, film, or story is the main male character, who usually has good qualities.","ex":{"en":"The hero of Doctor Zhivago dies in 1929.","cn":"《日瓦戈医生》的男主角于1929年去世。"}},{"pos":"N-COUNT 可数名词","cn":"（尤指男性）英雄，英雄人物，豪杰，勇士","en":"A hero is someone, especially a man, who has done something brave, new, or good, and who is therefore greatly admired by a lot of people.","ex":{"en":"He called Mr Mandela a hero who had inspired millions.","cn":"他称曼德拉先生为鼓舞了数百万民众的英雄。"}},{"pos":"N-COUNT 可数名词","cn":"偶像;崇拜对象;心目中的英雄","en":"If you describe someone as your hero, you mean that you admire them a great deal, usually because of a particular quality or skill that they have.","ex":{"en":"My boyhood hero was Bobby Charlton","cn":"我童年时代的偶像是博比·查尔顿。"}}]},"examples":[{"en":"The Olympic team were given a hero's welcome on their return home.","cn":"奥运代表队回国时受到了英雄般的欢迎。"},{"en":"The hero of the novel is a ten-year old boy.","cn":"这部小说的主人公是个十岁的男孩。"}]},"headword":{"oxford":{"phon":"ˈhedwɜːd","pos":"noun","senses":[{"en":"a word that forms a heading in a dictionary, under which its meaning is explained","cn":"（词典中的）词目，首词"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（词典中的）词目","en":"In a dictionary, a headword is a word which is followed by an explanation of its meaning."}]},"media":{"uk":"media/uk/headword__gb_1.mp3","us":"media/us/headword__us_1.mp3"}},"hello":{"media":{"uk":"media/uk/hello__gb_1.mp3","us":"media/us/hello__us_1.mp3"},"oxford":{"phon":"həˈləʊ","pos":"exclamation, noun","senses":[{"en":"used as a greeting when you meet somebody, in an email, when you answer the phone or when you want to attract somebody’s attention","cn":"（用于问候、发电邮、接电话或引起注意）哈啰，喂，你好","ex":{"en":"Hello John, how are you?","cn":"哈啰，约翰，你好吗？"}},{"en":"used to show that you are surprised by something","cn":"（表示惊讶）嘿","lab":"British English","ex":{"en":"Hello, hello, what's going on here?","cn":"嘿，嘿，这是在干吗？"}},{"en":"used to show that you think somebody has said something stupid or is not paying attention","cn":"（认为别人说了蠢话或分心）喂，嘿","lab":"informal","ex":{"en":"Hello? You didn't really mean that, did you?","cn":"嘿？你不会真是那个意思吧？"}},{"en":"a popular magazine published each week in Britain which contains photographs of and articles about famous people, and is known for saying only good things about them. It was first published in Britain in 1988 as a British version of the Spanish magazine ¡Hola!. The Hello! website is updated with news every day.","cn":"你好！：每周在英国发行的一本流行杂志，其中载有名人的照片和文章，并因只说出好话而闻名。它于1988年在英国首次发行，当时是西班牙杂志《 Hola！》的英文版。你好！网站每天都会更新新闻。","pos":""}]},"collins":{"senses":[{"pos":"CONVENTION 惯用语","cn":"哈罗;你好","en":"You say 'Hello' to someone when you meet them.","ex":{"en":"Hello, Trish","cn":"你好，特里茜。"}},{"pos":"CONVENTION 惯用语","cn":"（打电话时的招呼语）喂","en":"You say 'Hello' to someone at the beginning of a telephone conversation, either when you answer the phone or before you give your name or say why you are phoning.","ex":{"en":"A moment later, Cohen picked up the phone. 'Hello?'","cn":"过了一会儿，科恩接起电话。“喂？”"}},{"pos":"CONVENTION 惯用语","cn":"（用于引起别人注意）喂","en":"You can call 'hello' to attract someone's attention.","ex":{"en":"She could see the open door of a departmental office. 'Hello! Excuse me. This is the department of French, isn't it?'","cn":"她看到一个系办公室的门开着。“喂！请问，这是法语系，对吗？”"}}]},"examples":[{"en":"‘Hello, Mark.’ ‘Oh, hi, Kathy! How are you?’ “","cn":"马克，你好。” “噢，凯西，你好！最近好吗？”"},{"en":"I'm like, ‘Hello! Did you even listen?’","cn":"我说：“嘿！你到底有没有听我说话？”"}]},"hers":{"oxford":{"phon":"hɜːz","pos":"pronoun","senses":[{"en":"of or belonging to her","cn":"她的；属于她的","lab":"British English","ex":{"en":"His eyes met hers.","cn":"他的目光和她的相遇了。"}}]},"collins":{"senses":[{"pos":"PRON-POSS 所有格代词","cn":"她的(东西)","en":"You use hers to indicate that something belongs or relates to a woman, girl, or female animal.","ex":{"en":"His hand as it shook hers was warm and firm","cn":"和她握手时他的手温暖而有力。"}},{"pos":"PRON-POSS 所有格代词","cn":"（书面英语中泛指人）他的，她的（有些人不喜欢这种用法，更倾向于使用 his or hers 或 theirs）","en":"In written English, hers is sometimes used to refer to a person without saying whether that person is a man or a woman. Some people dislike this use and prefer to use 'his or hers' or 'theirs'.","ex":{"en":"The author can report other people's results which more or less agree with hers.","cn":"作者可以提及其他人得出的和她自己基本吻合的结果。"}},{"pos":"PRON-POSS 所有格代词","cn":"（指国家或民族）她的，它的","en":"Hers is sometimes used to refer to a country or nation."},{"pos":"PRON-POSS 所有格代词","cn":"（指汽车、机器或船）她的，它的","en":"People sometimes use hers to refer to a car, machine, or ship."}]},"media":{"uk":"media/uk/hers__gb_1.mp3","us":"media/us/hers__us_1.mp3"},"examples":[{"en":"His eyes met hers.","cn":"他的目光和她的相遇了。"},{"en":"The choice was hers.","cn":"那个选择是她做出的。"}]},"helicopter":{"media":{"img":["media/ldoce/img/helicopter.jpg","media/pic/aircraft_comp.jpg"],"uk":"media/uk/helicopter__gb_1.mp3","us":"media/us/helicopter__us_1.mp3"},"oxford":{"phon":"ˈhelɪkɒptə(r)","pos":"noun","senses":[{"en":"an aircraft without wings that has large blades (= long flat parts) on top that go round. It can fly straight up from the ground and can also stay in one position in the air.","cn":"直升机","ex":{"en":"a police/rescue helicopter","cn":"警用／救援直升机"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"直升机","en":"A helicopter is an aircraft with long blades on top that go round very fast. It is able to stay still in the air and to move straight upwards or downwards."}]},"examples":[{"en":"He was rushed to the hospital by helicopter.","cn":"他由直升机火速送到医院。"},{"en":"a helicopter pilot","cn":"直升机驾驶员"}]},"heaving":{"media":{"uk":"media/uk/heaving__gb_1.mp3","us":"media/us/heaving__us_1.mp3"},"oxford":{"phon":"ˈhiːvɪŋ","pos":"adjective","senses":[{"en":"full of somebody/something","cn":"充满（人或事物）","ex":{"en":"The place was heaving with journalists.","cn":"那个地方挤满了记者。"}}]},"examples":[{"en":"The place was heaving with journalists.","cn":"那个地方挤满了记者。"},{"en":"The city was heaving with shoppers.","cn":"这个城市挤满了购物者。"}],"base":"heave"},"heats":{"lemma":"heat","media":{"uk":"media/uk/heat__gb_1.mp3","us":"media/us/heat__us_1.mp3"}},"header":{"oxford":{"phon":"ˈhedə(r)","pos":"noun","senses":[{"en":"an act of hitting the ball with your head","cn":"用头顶球；头球"},{"en":"a line or block of text that appears at the top of every page in a book or document","cn":"页眉；页首","ex":{"en":"The header gives the page number and date of the document.","cn":"页眉印有页码和文档日期。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（足球）头球","en":"In football, a header is the act of hitting the ball in a particular direction with your head."},{"pos":"N-COUNT 可数名词","cn":"（文件的）页眉","en":"A header is text such as a name or a page number that can be automatically displayed at the top of each page of a printed document.","ex":{"en":"...page formatting like headers, footers and page numbers.","cn":"页眉、页脚、页码等页面格式"}}]},"media":{"uk":"media/uk/header__gb_1.mp3","us":"media/us/header__us_1.mp3"}},"helpless":{"media":{"uk":"media/uk/helpless__gb_1.mp3","us":"media/us/helpless__us_1.mp3"},"oxford":{"phon":"ˈhelpləs","pos":"adjective","senses":[{"en":"unable to take care of yourself or do things without the help of other people","cn":"无自理能力的；不能自立的；无助的","ex":{"en":"Children are the most helpless victims of war.","cn":"儿童是战争中最无助的受害者。"}},{"en":"unable to control a strong feeling","cn":"无法抑制的","ex":{"en":"helpless panic/rage","cn":"抑制不住的恐慌／愤怒"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无助的;无力量的;无能力的;不由自主的","en":"If you are helpless, you do not have the strength or power to do anything useful or to control or protect yourself.","ex":{"en":"Parents often feel helpless, knowing that all the cuddles in the world won't stop the tears","cn":"父母经常感到无能为力，因为他们知道无论多少次拥抱也无法止住眼泪。"}}]},"examples":[{"en":"They watched helplessly as their home went up in flames.","cn":"他们无奈地看着自己的家被大火吞没。"},{"en":"It's natural to feel helpless against such abuse.","cn":"对这种虐待感到无能为力是自然的。"}]},"heyday":{"media":{"uk":"media/uk/heyday__gb_1.mp3","us":"media/us/heyday__us_1.mp3"},"oxford":{"phon":"ˈheɪdeɪ","pos":"noun","senses":[{"en":"the time when somebody/something had most power or success, or was most popular","cn":"最为强大（或成功、繁荣）的时期","ex":{"en":"In its heyday, the company ran trains every fifteen minutes.","cn":"公司在最兴隆时期每隔十五分钟就开出一列火车。"}}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"全盛时期","en":"Someone's heyday is the time when they are most powerful, successful, or popular.","ex":{"en":"In its heyday, the studio's boast was that it had more stars than there are in heaven.","cn":"在其全盛时期，该制片公司夸口说，他们旗下的明星比天上的星星还要多。"}}]},"examples":[{"en":"In its heyday, the company ran trains every fifteen minutes.","cn":"公司在最兴隆时期每隔十五分钟就开出一列火车。"},{"en":"a fine example from the heyday of Italian cinema","cn":"意大利电影业全盛期的一部优秀代表作"}]},"healthy":{"media":{"uk":"media/uk/healthy__gb_1.mp3","us":"media/us/healthy__us_1.mp3"},"oxford":{"phon":"ˈhelθi","pos":"adjective","senses":[{"en":"having good health and not likely to become ill","cn":"健康的；健壮的","lab":"especially British English","ex":{"en":"a healthy child/baby/adult","cn":"健康的孩子／宝宝／成人"}},{"en":"good for your health","cn":"有益健康的","g":"[usually before noun]","ex":{"en":"a healthy diet/lifestyle","cn":"健康的饮食／生活方式"}},{"en":"showing that you are in good health","cn":"反映健康的","g":"[usually before noun]","ex":{"en":"to have a healthy appetite","cn":"胃口好"}},{"en":"normal and sensible","cn":"正常合理的","ex":{"en":"The child showed a healthy curiosity.","cn":"这孩子的好奇心很正常。"}},{"en":"successful and working well","cn":"兴旺的；发达的；顺利的","ex":{"en":"The economy is extremely healthy at the moment.","cn":"目前经济极为繁荣。"}},{"en":"large and showing success","cn":"大而显得成功的；可观的","g":"[usually before noun]","ex":{"en":"a healthy bank balance","cn":"一大笔银行结余"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"健康的;健壮的","en":"Someone who is healthy is well and is not suffering from any illness.","ex":{"en":"Most of us need to lead more balanced lives to be healthy and happy","cn":"我们中大多数人需要过更为平衡的生活，以保持健康和快乐。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"显示健康的;反映健康的","en":"If a feature or quality that you have is healthy, it makes you look well or shows that you are well.","ex":{"en":"...the glow of healthy skin.","cn":"健康的肤色"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有益于健康的;促进健康的","en":"Something that is healthy is good for your health.","ex":{"en":"...a great healthy outdoor pursuit.","cn":"对健康大有裨益的室外活动"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（机构或体系）兴旺的，运作良好的","en":"A healthy organization or system is successful.","ex":{"en":"...an economically healthy socialist state.","cn":"经济繁荣的社会主义国家"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"大量的;可观的","en":"A healthy amount of something is a large amount that shows success.","ex":{"en":"He predicts a continuation of healthy profits in the current financial year.","cn":"他预计本财年能继续保持可观的利润。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"明智的;聪明的;合理的","en":"If you have a healthy attitude about something, you show good sense.","ex":{"en":"She has a refreshingly healthy attitude to work","cn":"她对工作持一种明智态度，令人耳目一新。"}}]},"examples":[{"en":"Keep healthy by eating well and exercising regularly.","cn":"通过良好饮食和经常性锻炼保持健康。"},{"en":"It's not healthy the way she clings to the past.","cn":"她那种沉湎于过去的态度不明智。"}]},"here":{"media":{"uk":"media/uk/here__gb_1.mp3","us":"media/us/here__us_1.mp3"},"oxford":{"phon":"hɪə(r)","pos":"adverb","senses":[{"en":"used after a verb or preposition to mean ‘in, at or to this position or place’","cn":"（用于动词或介词之后）在这里，向这里","ex":{"en":"I live here.","cn":"我住这儿。"}},{"en":"used when you are giving or showing something to somebody","cn":"（给某人东西或指出某物时说）","ex":{"en":"Here's the money I promised you.","cn":"这是我答应给你的钱。"}},{"en":"used to show your role in a situation","cn":"（表示某人的作用）","ex":{"en":"I'm here to help you.","cn":"我是来帮助你的。"}},{"en":"now; at this point","cn":"现在；在这一点上","ex":{"en":"The countdown to Christmas starts here.","cn":"现在开始圣诞节倒计时。"}},{"en":"used to attract somebody’s attention","cn":"（用以引起注意）喂，嘿","lab":"British English","ex":{"en":"Here, where are you going with that ladder?","cn":"嘿，你要把梯子搬到哪里？"},"pos":"exclamation"},{"en":"used when offering something to somebody","cn":"（主动提议时说）","ex":{"en":"Here, let me carry that for you.","cn":"来，让我帮你搬吧。"},"pos":"exclamation"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"在这里;在这儿","en":"You use here when you are referring to the place where you are.","ex":{"en":"I'm here all by myself and I know I'm going to get lost","cn":"这里只有我一个人，我知道我会迷路的。"}},{"pos":"ADV 副词","cn":"在此处（指所指向的地方）","en":"You use here when you are pointing towards a place that is near you, in order to draw someone else's attention to it.","ex":{"en":"...if you will just sign here","cn":"请在这里签字"}},{"pos":"ADV 副词","cn":"在身边;在手里","en":"You use here in order to indicate that the person or thing that you are talking about is near you or is being held by you.","ex":{"en":"My friend here writes for radio","cn":"我这位朋友是个电台撰稿人。"}},{"pos":"ADV 副词","cn":"在人世间","en":"You use here to refer to people in general and their life on Earth.","ex":{"en":"...where we have come from, where we are going to, or what our purpose here is, if any","cn":"我们从哪里来，到哪里去，或者倘若我们活在人世间有何目的的话，这个目的是什么"}},{"pos":"ADV 副词","cn":"来此（做…）","en":"If you say that you are here to do something, that is your role or function.","ex":{"en":"I'm here to help you","cn":"我是来帮你的。"}},{"pos":"ADV 副词","cn":"（用于引起注意）…来了，…到了","en":"You use here in order to draw attention to something or someone who has just arrived in the place where you are, or to draw attention to the place you have just arrived at.","ex":{"en":"'Here's the taxi,' she said politely","cn":"“出租车来了，”她礼貌地说。"}},{"pos":"ADV 副词","cn":"在这一点上;在这一阶段;在这一方面","en":"You use here to refer to a particular point or stage of a situation or subject that you have come to or that you are dealing with.","ex":{"en":"Both sides will have to sell the agreement to their people. It's here that the real test will come","cn":"双方都必须要让各自的民众接受这项协议。真正的考验就在这里。"}},{"pos":"ADV 副词","cn":"这时;此刻","en":"You use here to refer to a period of time, a situation, or an event that is present or happening now.","ex":{"en":"Here comes the summer","cn":"夏天到了。"}},{"pos":"ADV 副词","cn":"（用在句首以引起注意或引出介绍）下面，以下","en":"You use here at the beginning of a sentence in order to draw attention to something or to introduce something.","ex":{"en":"From Nairobi here's our East Africa correspondent, Colin Blane","cn":"以下是我们来自内罗毕的东非记者科林·布兰的报道。"}},{"pos":"ADV 副词","cn":"给（对方）","en":"You use here when you are offering or giving something to someone.","ex":{"en":"You know you can phone me — here's my mother's number","cn":"你可以给我打电话——给你，这是我母亲的电话号码。"}},{"pos":"PHRASE 短语","cn":"（表示接下来对某人性格或处境的描述出人意料）看看，瞧瞧","en":"You say 'here we are' or 'here you are' when the statement that you are making about someone's character or situation is unexpected.","ex":{"en":"Here you are, saying these terrible things","cn":"看看你，说这些难听的话。"}},{"pos":"CONVENTION 惯用语","cn":"找到了; 这就是了","en":"You say 'here we are' when you have just found something that you have been looking for.","ex":{"en":"I rummaged through the drawers and came up with Amanda's folder. 'Here we are.'","cn":"我翻遍了抽屉，找出了阿曼达的文件夹。“找到了。”"}},{"pos":"CONVENTION 惯用语","cn":"（表示即将开始做或说困难或令人不快的事）这就开始","en":"You say 'here goes' when you are about to do or say something difficult or unpleasant.","ex":{"en":"Dr Culver nervously muttered 'Here goes,' and gave the little girl an injection.","cn":"卡尔弗医生紧张地嘟囔了一句“要打了啊”，然后就给小女孩打了一针。"}},{"pos":"PHRASE 短语","cn":"（尤指令人不快的事）又发生了，又来了","en":"You use expressions such as 'here we go' and 'here we go again' in order to indicate that something is happening again in the way that you expected, especially something unpleasant.","ex":{"en":"'Police! Open up!' — 'Oh well,' I thought, 'here we go.'","cn":"“警察！开门！”——“哎呀。”我想，“又来了。”"}},{"pos":"PHRASE 短语","cn":"此时此刻;目前;眼下","en":"You use here and now to emphasize that something is happening at the present time, rather than in the future or past, or that you would like it to happen at the present time.","ex":{"en":"I'm a practicing physician trying to help people here and now","cn":"我是一名此时此刻只想治病救人的执业医师。"}},{"pos":"PHRASE 短语","cn":"在各处;零散地","en":"If something happens here and there, it happens in several different places.","ex":{"en":"I do a bit of teaching here and there","cn":"我零零散散地到处教些课。"}},{"pos":"CONVENTION 惯用语","cn":"（祝酒词）为我们干杯/为你的新工作干杯","en":"You use expressions such as 'here's to us' and 'here's to your new job' before drinking a toast in order to wish someone success or happiness.","ex":{"en":"He raised his glass. 'Here's to neighbors.'","cn":"他举起杯子： “各位高邻，干了这杯！”"}}]},"examples":[{"en":"‘Here we go,’ thought Fred, ‘she's sure to say something.’ “","cn":"这就开始了。”弗雷德想，“她肯定有话要说。”"},{"en":"I can't find my keys. Oh, here they are.","cn":"我找不到我的钥匙。哦，原来在这里。"}]},"hears":{"lemma":"hear","media":{"uk":"media/uk/hear__gb_1.mp3","us":"media/us/hear__us_1.mp3"}},"heath":{"media":{"uk":"media/uk/heath__gb_1.mp3","us":"media/us/heath__us_1.mp3"},"oxford":{"phon":"hiːθ","pos":"noun","senses":[{"en":"a large area of open land that is not used for farming and is covered with rough grass and other small wild plants","cn":"（杂草和灌木丛生的）荒地，荒野","ex":{"en":"Wild ponies roam free on the heath.","cn":"野生小马在荒原上自由漫步。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（野草或石南丛生的）荒野，荒原","en":"A heath is an area of open land covered with rough grass or heather and with very few trees or bushes."}]}},"hen":{"oxford":{"phon":"hen","pos":"noun","senses":[{"en":"a female chicken, often kept for its eggs or meat","cn":"母鸡","ex":{"en":"a small flock of laying hens","cn":"一小群下蛋的母鸡"}},{"en":"any female bird","cn":"雌禽","ex":{"en":"a hen pheasant","cn":"雌雉"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"母鸡","en":"A hen is a female chicken. People often keep hens in order to eat them or sell their eggs."},{"pos":"N-COUNT 可数名词","cn":"雌禽","en":"The female of any bird can be referred to as a hen .","ex":{"en":"...ostrich hens.","cn":"雌性鸵鸟"}}]},"media":{"uk":"media/uk/hen__gb_1.mp3","us":"media/us/hen__us_1.mp3"},"examples":[{"en":"a small flock of laying hens","cn":"一小群下蛋的母鸡"},{"en":"battery hens","cn":"层架式鸡笼饲养的母鸡"}]},"helpful":{"oxford":{"phon":"ˈhelpfl","pos":"adjective","senses":[{"en":"able to improve a particular situation","cn":"有用的；有益的；有帮助的","ex":{"en":"helpful advice/information","cn":"有用的忠告／信息"}},{"en":"willing to help somebody","cn":"愿意帮忙的","ex":{"en":"I called the police but they weren't very helpful.","cn":"我叫了警察，但他们不太肯帮忙。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（人）给予帮助的，帮上忙的","en":"If you describe someone as helpful, you mean that they help you in some way, such as doing part of your job for you or by giving you advice or information.","ex":{"en":"The staff in the London office are helpful but only have limited information","cn":"伦敦办事处的工作人员给予了帮助，但他们掌握的信息有限。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（信息、建议等）有帮助的，有用的","en":"If you describe information or advice as helpful, you mean that it is useful for you.","ex":{"en":"The catalog includes helpful information on the different bike models available","cn":"目录中包括了在售的各种型号自行车的有用信息。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(事物）有助于改善局面的，有好处的","en":"Something that is helpful makes a situation more pleasant or more easy to tolerate.","ex":{"en":"A predominantly liquid diet for a day or two may be helpful","cn":"一两天里主要吃流质食物可能会有好处。"}}]},"media":{"uk":"media/uk/helpful__gb_1.mp3","us":"media/us/helpful__us_1.mp3"},"examples":[{"en":"It would be helpful for me to see the damage for myself.","cn":"要能亲眼看看造成的破坏会对我有所帮助。"},{"en":"The booklet should be very helpful to parents of disabled children.","cn":"这本小册子对于残疾儿童的父母会很有用。"}]},"hence":{"media":{"uk":"media/uk/hence__gb_1.mp3","us":"media/us/hence__us_1.mp3"},"oxford":{"phon":"hens","pos":"adverb","senses":[{"en":"for this reason","cn":"因此；由此","ex":{"en":"We suspect they are trying to hide something, hence the need for an independent inquiry.","cn":"我们怀疑他们在企图隐瞒什么事，因此有必要进行独立调查。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"因此;由此;所以","en":"You use hence to indicate that the statement you are about to make is a consequence of what you have just said.","ex":{"en":"The trade imbalance is likely to rise again in 1990. Hence a new set of policy actions will be required soon","cn":"贸易失衡可能会在1990年再次加剧。因此需要很快采取一系列新的政策行动。"}},{"pos":"ADV 副词","cn":"（尤指未来的长时间）之后","en":"You use hence in expressions such as 'several years hence' or 'six months hence' to refer to a time in the future, especially a long time in the future.","ex":{"en":"The gases that may be warming the planet will have their main effect many years hence.","cn":"可能正导致地球变暖的那些气体，其主要影响将在多年后显现。"}}]},"examples":[{"en":"We suspect they are trying to hide something, hence the need for an independent inquiry.","cn":"我们怀疑他们在企图隐瞒什么事，因此有必要进行独立调查。"},{"en":"The true consequences will only be known several years hence.","cn":"真正的后果只有在几年之后才能知道。"}]},"health":{"media":{"uk":"media/uk/health__gb_1.mp3","us":"media/us/health__us_1.mp3"},"oxford":{"phon":"helθ","pos":"noun","senses":[{"en":"the condition of a person’s body or mind","cn":"人的身体（或精神）状况；健康","ex":{"en":"to be good/bad for your health","cn":"对健康有益／有害"}},{"en":"the state of being physically and mentally healthy","cn":"健康","ex":{"en":"Slowly they nursed him back to health.","cn":"他们慢慢地护理他恢复健康。"}},{"en":"the work of providing medical services","cn":"医疗；保健；卫生","ex":{"en":"All parties are promising to increase spending on health.","cn":"各政党都在许诺增加医疗开支。"}},{"en":"how successful something is","cn":"状况；牢靠性","ex":{"en":"the health of the economy","cn":"经济健康状况"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"健康状况;身体状况","en":"A person's health is the condition of their body and the extent to which it is free from illness or is able to resist illness.","ex":{"en":"Caffeine is bad for your health.","cn":"咖啡因对人体健康有害。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"健康","en":"Health is a state in which a person is not suffering from any illness and is feeling well.","ex":{"en":"In hospital they nursed me back to health.","cn":"在医院里他们对我进行治疗及护理，使我恢复了健康。"}},{"pos":"PHRASE 短语","cn":"为…的健康干杯","en":"When you drink to someone's health or drink their health, you have a drink as a sign of wishing them health and happiness.","ex":{"en":"In the village pub, regulars drank the health of John and his father.","cn":"在村子的酒馆里，老顾客们举杯祝愿约翰和他的父亲身体健康。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"兴旺;良好运行","en":"The health of something such as an organization or a system is its success and the fact that it is working well.","ex":{"en":"There's no way to predict the future health of the banking industry.","cn":"银行业未来是否会兴旺发达根本无法预测。"}}]},"examples":[{"en":"As long as you have your health, nothing else matters.","cn":"只要身体健康，其他任何事都无关紧要。"},{"en":"She was glowing with health and clearly enjoying life.","cn":"她容光焕发，显然生活得很快活。"}]},"headquartered":{"media":{"uk":"media/uk/headquartered__gb_1.mp3","us":"media/us/headquartered__us_1.mp3"},"oxford":{"phon":"ˌhedˈkwɔːtəd","pos":"adjective","senses":[{"en":"having headquarters in a particular place","cn":"总部在某地","ex":{"en":"News Corporation is headquartered in New York.","cn":"新闻集团的总部设在纽约。"}}]},"collins":{"senses":[{"pos":"V-PASSIVE 被动动词","cn":"总部设在…","en":"If an organization is headquartered in a particular place, that is where its main offices are.","ex":{"en":"The company is headquartered in Chicago.","cn":"公司总部设在芝加哥。"}}]},"examples":[{"en":"News Corporation is headquartered in New York.","cn":"新闻集团的总部设在纽约。"},{"en":"Many top companies are headquartered in northern California.","cn":"很多大公司都把总部设在加利福尼亚北部。"}]},"herald":{"media":{"uk":"media/uk/herald__gb_1.mp3","us":"media/us/herald__us_1.mp3"},"oxford":{"phon":"ˈherəld","pos":"verb","senses":[{"en":"to be a sign that something is going to happen","cn":"是（某事）的前兆；预示","ex":{"en":"These talks could herald a new era of peace.","cn":"这些谈判可能预示着新的和平时代的来临。"}},{"en":"to say in public that somebody/something is good or important","cn":"宣称（…是好的或重要的）","g":"[often passive]","ex":{"en":"The report is being heralded as a blueprint for the future of transport.","cn":"这份报告被宣称是未来运输的蓝图。"}},{"en":"something that shows that something else is going to happen soon","cn":"预兆","ex":{"en":"The government claims that the fall in unemployment is the herald of economic recovery.","cn":"政府宣称失业人数减少是经济复苏的先兆。"},"pos":"noun"},{"en":"a person who made announcements and carried messages from a ruler","cn":"信使；传令官；使者","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"预告;预示…的来临","en":"Something that heralds a future event or situation is a sign that it is going to happen or appear.","ex":{"en":"...the sultry evening that heralded the end of the baking hot summer","cn":"预示着炙热的夏天即将结束的闷热夜晚"}},{"pos":"N-COUNT 可数名词","cn":"预兆","en":"Something that is a herald of a future event or situation is a sign that it is going to happen or appear.","ex":{"en":"I welcome the report as a herald of more freedom, not less","cn":"我认为这份报告预示着会有更多、而不是更少的自由，因此对它表示欢迎。"}},{"pos":"VERB 动词","cn":"宣布;报告…的消息","en":"If an important event or action is heralded by people, announcements are made about it so that it is publicly known and expected.","ex":{"en":"Janet Jackson's new album has been heralded by a massive media campaign","cn":"珍妮·杰克逊的新专辑已经在媒体上进行了大规模宣传。"}},{"pos":"N-COUNT 可数名词","cn":"（古时的）传令官，使节","en":"In former times, a herald was a person who delivered and announced important messages."}]},"examples":[{"en":"These talks could herald a new era of peace.","cn":"这些谈判可能预示着新的和平时代的来临。"},{"en":"The government claims that the fall in unemployment is the herald of economic recovery.","cn":"政府宣称失业人数减少是经济复苏的先兆。"}]},"help":{"media":{"uk":"media/uk/help__gb_1.mp3","us":"media/us/help__us_1.mp3"},"oxford":{"phon":"help","pos":"verb","senses":[{"en":"to make it easier or possible for somebody to do something by doing something for them or by giving them something that they need","cn":"帮助；协助；援助","g":"[intransitive, transitive]","lab":"informal or North American English","sc":"make easier/better","ex":{"en":"What can I do to help?","cn":"我能提供什么帮助吗？"}},{"en":"to improve a situation; to make it easier for something to happen","cn":"改善状况；促进；促使","g":"[intransitive, transitive]","sc":"make easier/better","ex":{"en":"The support of our families has helped enormously.","cn":"家庭的支持给了我们巨大的帮助。"}},{"en":"to help somebody move or do some other action by letting them lean on you, guiding them, etc.","cn":"搀扶；扶着走；带领","g":"[transitive]","sc":"somebody to move","ex":{"en":"She helped him to his feet.","cn":"她扶他站了起来。"}},{"en":"to give yourself/somebody food, drinks, etc.","cn":"为（自己或某人）取用","g":"[transitive]","sc":"give food/drink","ex":{"en":"If you want another drink, just help yourself.","cn":"你要是想再喝一杯就请自便。"}},{"en":"to take something without permission","cn":"擅自拿走；窃取","g":"[transitive]","lab":"informal, disapproving，，","sc":"steal","ex":{"en":"He'd been helping himself to the money in the cash register.","cn":"他一直在偷现金出纳机中的钱。"}},{"en":"the act of helping somebody to do something","cn":"帮助；协助；援助","g":"[uncountable]","sc":"making easier/better","ex":{"en":"Thank you for all your help.","cn":"感谢你的一切帮助。"},"pos":"noun"},{"en":"the act of helping somebody who is in danger","cn":"救助","g":"[uncountable]","sc":"for somebody in danger","ex":{"en":"Quick, get help!","cn":"快，找人援救！"},"pos":"noun"},{"en":"advice, money, etc. that is given to somebody in order to solve their problems","cn":"有助益的东西（如忠告、钱等）","g":"[uncountable]","sc":"advice/money","ex":{"en":"professional/medical/financial help","cn":"专业／医疗／财政援助"},"pos":"noun"},{"en":"a function on a computer, phone, etc. that provides information on how to use the computer, phone, etc.","cn":"（计算机、电话等的）帮助功能","g":"[uncountable]","sc":"on a computer/phone, etc.","ex":{"en":"The online help is very good.","cn":"线上帮助功能很有用。"},"pos":"noun"},{"en":"the fact of being useful","cn":"有用","g":"[uncountable]","sc":"being useful","ex":{"en":"The map wasn't much help.","cn":"这张地图没多大用处。"},"pos":"noun"},{"en":"a person or thing that helps somebody","cn":"有帮助的人（或事物）","g":"[singular]","lab":"ironic","sc":"person/thing","ex":{"en":"She was more of a hindrance than a help.","cn":"她非但没帮上忙，反而碍事。"},"pos":"noun"},{"en":"the person or people employed by somebody to clean their house, etc.","cn":"帮工；家政人员","g":"[uncountable + singular or plural verb]","lab":"especially North American English","sc":"in house","pos":"noun"},{"en":"used to call for help because you are in a dangerous situation","cn":"救命（遇到危险时用于呼救）","ex":{"en":"Help, I'm stuck!","cn":"救命，我被卡住了！"},"pos":"exclamation"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"帮助;帮忙","en":"If you help someone, you make it easier for them to do something, for example by doing part of the work for them or by giving them advice or money.","ex":{"en":"He has helped to raise a lot of money","cn":"他帮着筹集了很多钱。"}},{"pos":"VERB 动词","cn":"有帮助;有用","en":"If you say that something helps, you mean that it makes something easier to do or get, or that it improves a situation to some extent.","ex":{"en":"The right style of swimsuit can help to hide, minimise or emphasise what you want it to","cn":"款式选择得当的泳装有助于按照意愿掩饰、缩小或突出某些部位。"}},{"pos":"VERB 动词","cn":"扶持;搀扶","en":"If you help someone go somewhere or move in some way, you give them support so that they can move more easily.","ex":{"en":"Martin helped Tanya over the rail","cn":"马丁扶着塔尼娅越过栏杆。"}},{"pos":"VERB 动词","cn":"帮助（自己）摆脱困境","en":"If you help yourself, you try to get yourself out of a difficult situation rather than accept it and think you can do nothing to change it.","ex":{"en":"He tries to help people with problems, but firmly believes they should do more to help themselves.","cn":"他尽力帮助有困难的人，但仍坚信他们应该更加努力自救。"}},{"pos":"N-SING 单数名词","cn":"帮助解决困难的人（或事物）","en":"If you say that someone or something has been a help or has been some help, you mean that they have helped you to solve a problem.","ex":{"en":"Thank you. You've been a great help already.","cn":"谢谢你。你已经帮了大忙了。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"援救;救命","en":"Help is action taken to rescue a person who is in danger. You shout 'help!' when you are in danger in order to attract someone's attention so that they can come and rescue you.","ex":{"en":"He was screaming for help","cn":"他高呼求救。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"帮助（文件）","en":"In computing, help, or the help menu, is a file that gives you information and advice, for example about how to use a particular program.","ex":{"en":"If you get stuck, click on Help.","cn":"如果碰到疑难，就点击“帮助”。"}},{"pos":"VERB 动词","cn":"自助;自取","en":"If you help yourself to something, you serve yourself or you take it for yourself. If someone tells you to help yourself, they are telling you politely to serve yourself anything you want or to take anything you want.","ex":{"en":"There's bread on the table. Help yourself","cn":"桌上有面包。你自己拿吧。"}},{"pos":"VERB 动词","cn":"偷;窃取","en":"If someone helps themselves to something, they steal it.","ex":{"en":"Has somebody helped himself to some film star's diamonds?","cn":"有人偷了某个影星的钻石了吗？"}},{"pos":"PHRASE 短语","cn":"不禁;忍不住;无法控制","en":"If you can't help the way you feel or behave, you cannot control it or stop it happening. You can also say that you can't help yourself .","ex":{"en":"I can't help feeling sorry for the poor man","cn":"我不禁为这个可怜的男人感到难过。"}},{"pos":"PHRASE 短语","cn":"（用于委婉地表示观点）不免，禁不住（想）","en":"If you say you can't help thinking something, you are expressing your opinion in an indirect way, often because you think it seems rude.","ex":{"en":"I can't help feeling that this may just be another of her schemes","cn":"我不免觉得这可能只是她的又一个诡计。"}},{"pos":"PHRASE 短语","cn":"有帮助;有用","en":"If someone or something is of help, they make a situation easier or better.","ex":{"en":"Can I be of help to you?","cn":"我能帮上你吗？"}},{"pos":"","cn":"","en":"相关词组：help off with help on with help out"}]},"examples":[{"en":"I always end up having an argument with her, I don't know why, I just can't help it.","cn":"我总是和她意见不合，闹得不欢而散，我不知道为什么，我就是忍不住。"},{"en":"a help key/screen (= a function on a computer that provides information on how to use the computer)","cn":"帮助键/屏幕（计算机中提供计算机使用信息的功能）"}]},"heal":{"media":{"uk":"media/uk/heal__gb_1.mp3","us":"media/us/heal__us_1.mp3"},"oxford":{"phon":"hiːl","pos":"verb","senses":[{"en":"to become healthy again; to make something healthy again","cn":"（使）康复，复原","g":"[intransitive, transitive]","lab":"figurative","ex":{"en":"It took a long time for the wounds to heal.","cn":"伤口过了很长时间才愈合。"}},{"en":"to cure somebody who is ill; to make somebody feel happy again","cn":"治疗（病人）；使又愉快起来","g":"[transitive]","lab":"old use or formal","ex":{"en":"the story of Jesus healing ten lepers of their disease","cn":"耶稣治愈十个麻风病人的故事"}},{"en":"to put an end to something or make something easier to bear; to end or become easier to bear","cn":"（使）结束，较容易忍受","g":"[transitive, intransitive]","ex":{"en":"She was never able to heal the rift between herself and her father.","cn":"她一直未能填平和她父亲之间的鸿沟。"}}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"痊愈;愈合;治愈","en":"When a broken bone or other injury heals or when something heals it, it becomes healthy and normal again.","ex":{"en":"Within six weeks the bruising had gone, but it was six months before it all healed","cn":"青瘀在6周内就消退了，但伤却是6个月后才全好了。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（感情创伤）愈合;（情感）恢复常态","en":"When someone's emotional pain heals, they feel normal and happy again.","ex":{"en":"A year later, she had healed to the point of at least being able to consider a romantic relationship with another man","cn":"一年以后，她的感情创伤已慢慢愈合，至少能考虑和另一个男性开始恋爱关系了。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）（裂痕、创伤）弥合;（使）和好","en":"If you heal something such as a rift or a wound, or if it heals, the situation is put right so that people are friendly or happy again.","ex":{"en":"Today Sophie and her sister have healed the family rift and visit their family every weekend","cn":"如今索菲和她的姐姐已经和家人和好，每个周末都回家探望他们。"}},{"pos":"","cn":"","en":"相关词组：heal up"}]},"examples":[{"en":"She was never able to heal the rift between herself and her father.","cn":"她一直未能填平和她父亲之间的鸿沟。"},{"en":"The breach between them never really healed.","cn":"他们之间的裂痕从来没有真正弥合。"}]},"heavens":{"lemma":"heaven"},"helicopters":{"lemma":"helicopter"},"helps":{"lemma":"help"},"heroes":{"lemma":"hero"},"heels":{"lemma":"heel"},"helped":{"lemma":"help"},"heights":{"lemma":"height"},"heads":{"lemma":"head"},"heard":{"lemma":"hear"},"herding":{"lemma":"herd"},"heavier":{"lemma":"heavy"},"heightened":{"lemma":"heighten"},"hesitating":{"lemma":"hesitate"},"herbs":{"lemma":"herb","media":{"img":["media/pic/herbs_comp.jpg"]}},"herders":{"oxford":{"phon":"","pos":"noun","senses":[{"en":"a person whose job is to take care of a group of animals such as sheep and cows in the countryside","cn":"放牧人；牧工"}]}},"heaved":{"lemma":"heave"},"helpers":{"lemma":"helper"},"hesitated":{"lemma":"hesitate"},"hearsay":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"传闻;谣言;道听途说","en":"Hearsay is information which you have been told but do not know to be true.","ex":{"en":"Much of what was reported to them was hearsay","cn":"向他们汇报的消息中很多都是道听途说。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"information which is passed from one person to another and which may or may not be true, especially information about people's private lives or about something that a government, company etc has done or is planning to do","cn":""},{"en":"if there is speculation about something, especially about something that is happening in politics or public life, a lot of people are talking about it and trying to guess what the truth is - used especially in news reports","cn":""},{"en":"information which people tell each other about other people's private lives, and which may or may not be true, especially when this is done in an unkind or disapproving way","cn":""}]},"vocab":{"pos":"n adj","senses":[{"en":"Ever hear someone say something so juicy you decide to tell other people about it, even if you don't know if it's true or not? Admit it. That hearsay , or gossip, is precisely how rumors get started."}]},"collocations":{"phrases":["VERB + HEARSAY be based on, rely on Her judgements are based on hearsay rather than evidence.","HEARSAY + NOUN evidence","PREP. by ~ She discovered a world of parties and pleasure she had hitherto only known by hearsay. | from ~ They started to piece the story t"]},"media":{"uk":"media/ldoce/hwd/bre/8/hearsay0205.mp3","us":"media/ldoce/hwd/ame/a/hearsay.mp3"},"examples":[{"en":"We can't make a decision based on hearsay and guesswork.","cn":"我们不能根据传言和猜测作决定。"},{"en":"hearsay evidence","cn":"传闻的证据"}],"oxford":{"phon":"ˈhɪəseɪ","pos":"noun","senses":[{"en":"things that you have heard from another person but do not (definitely) know to be true","cn":"道听途说；传闻","ex":{"en":"We can't make a decision based on hearsay and guesswork.","cn":"我们不能根据传言和猜测作决定。"}}]}},"hedge":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"树篱","en":"A hedge is a row of bushes or small trees, usually along the edge of a garden, field, or road."},{"pos":"VERB 动词","cn":"防备，防范（尤指金钱损失）","en":"If you hedge against something unpleasant or unwanted that might affect you, especially losing money, you do something which will protect you from it.","ex":{"en":"You can hedge against redundancy or illness with insurance","cn":"可以购买保险以防失业或患病。"}},{"pos":"N-COUNT 可数名词","cn":"防护物;防备手段;防范措施","en":"Something that is a hedge against something unpleasant will protect you from its effects.","ex":{"en":"Gold is traditionally a hedge against inflation.","cn":"购买黄金是防范通货膨胀的一种传统手段。"}},{"pos":"VERB 动词","cn":"躲闪;回避","en":"If you hedge, you avoid answering a question or committing yourself to a particular action or decision.","ex":{"en":"They hedged in answering various questions about the operation","cn":"他们闪烁其词，不愿回答有关此次行动的各种问题。"}},{"pos":"PHRASE 短语","cn":"两面下注以防损失;骑墙","en":"If you hedge your bets, you reduce the risk of losing a lot by supporting more than one person or thing in a situation where they are opposed to each other.","ex":{"en":"Hawker Siddeley tried to hedge its bets by diversifying into other fields","cn":"霍克·西德利试图通过在其他领域进行多样化发展来规避风险。"}},{"pos":"","cn":"","en":"相关词组：hedge about"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an area of short grass in a garden","cn":""},{"en":"an area of ground where you grow flowers","cn":""},{"en":"an area of a garden where there are rocks with small flowers growing between them","cn":""}]},"vocab":{"pos":"1 n v 2 n v 3 n v","senses":[{"en":"A hedge is a living fence made of closely planted bushes, which, as they grow and get trimmed and shaped, form a wall of green."}]},"collocations":{"phrases":["ADJ. high, low, tall, thick | boundary, garden, roadside Establish which boundary hedges are yours, and which belong to a neighbour. | beech","VERB + HEDGE plant | clip, trim Trim the hedge and collect the trimmings.","HEDGE + NOUN clippings, trimmings | trimmer"]},"media":{"uk":"media/ldoce/hwd/bre/a/hedge_v0205.mp3","us":"media/ldoce/hwd/ame/2/hedge1.mp3"},"examples":[{"en":"Just answer ‘yes’ or ‘no’ — and stop hedging.","cn":"只要回答“是”或“不是”，别再闪烁其词了。"},{"en":"Their offer was hedged around with all sorts of conditions.","cn":"他们的建议附带了各种各样的限制条件。"}],"oxford":{"phon":"hedʒ","pos":"noun","senses":[{"en":"a row of bushes or small trees planted close together, usually along the edge of a field, garden or road","cn":"树篱","ex":{"en":"a privet hedge","cn":"女贞树篱"}},{"en":"a way of protecting yourself against the loss of something, especially money","cn":"防止损失（尤指金钱）的手段","ex":{"en":"I bought gold as a hedge against inflation.","cn":"我购买黄金是为了对冲通货膨胀。"}},{"en":"to avoid giving a direct answer to a question or promising to support a particular idea, etc.","cn":"避免正面回答；不直接许诺；拐弯抹角","g":"[intransitive]","ex":{"en":"Just answer ‘yes’ or ‘no’—and stop hedging.","cn":"只要回答“是”或“不是”，别再闪烁其词了。"},"pos":"verb"},{"en":"to put a hedge around a field, etc.","cn":"在（田地等）周围植树篱；用树篱围住","g":"[transitive]","pos":"verb"},{"en":"to surround or limit somebody/something","cn":"包围；限制","g":"[transitive, usually passive]","lab":"formal","ex":{"en":"His religious belief was always hedged with doubt.","cn":"他的宗教信仰一直受到心不诚的局限。"},"pos":"verb"}]}},"heir":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"继承人","en":"An heir is someone who has the right to inherit a person's money, property, or title when that person dies.","ex":{"en":"His heir, Lord Doune, cuts a bit of a dash in the city.","cn":"他的继承人杜恩勋爵在城里出了一番风头。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the person who has the legal right to receive the property or title of another person when they die","cn":"继承人"},{"en":"the person who will take over a position or job after you, or who does things or thinks in a similar way to you","cn":"继任人﹐接班人"}]},"vocab":{"pos":"n","senses":[{"en":"If your grandfather leaves his candy factory to you in his will, it means you're the heir to the family candy business, and after your grandfather dies, you will inherit the factory."}]},"collocations":{"phrases":["ADJ. lawful, legal, legitimate, rightful the rightful heir to the throne | natural, real, true The socialists saw themselves as true heirs o","VERB + HEIR have He has no heir to leave his fortune to. | beget, get, produce He planned to marry and produce an heir for his estate. | bec","PREP. ~ to He is the sole heir to a large mining fortune.","PHRASES the heir to the throne, sb's son and heir He left most of his property to his eldest son and heir."]},"media":{"uk":"media/ldoce/hwd/bre/6/brelasdeheir.mp3","us":"media/ldoce/hwd/ame/f/air1.mp3"},"examples":[{"en":"to be heir to a large fortune","cn":"是大笔财产的继承人"},{"en":"the heir to the throne (= the person who will be the next king or queen)","cn":"王位继承人"}],"oxford":{"phon":"eə(r)","pos":"noun","senses":[{"en":"a person who has the legal right to receive somebody’s property, money or title when that person dies","cn":"继承人；后嗣","ex":{"en":"to be heir to a large fortune","cn":"是大笔财产的继承人"}},{"en":"a person who is thought to continue the work or a tradition started by somebody else","cn":"（工作或传统的）继承者，承袭者，传人","ex":{"en":"the president’s political heirs","cn":"总统的政治继承者"}}]}},"hernia":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"（脏器的）突出;疝（气）","en":"A hernia is a medical condition which is often caused by strain or injury. It results in one of your internal organs sticking through a weak point in the surrounding tissue."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a medical condition in which an organ pushes through the muscles that are supposed to contain it","cn":"疝气"}]},"vocab":{"pos":"n","senses":[{"en":"A hernia is a rip in your muscle tissue that leads to an organ protruding through the muscle. It's painful and dangerous."}]},"collocations":{"phrases":["VERB + HERNIA have, suffer from | remove, repair","HERNIA + NOUN operation, repair •"]},"media":{"uk":"media/ldoce/hwd/bre/f/hernia0205.mp3","us":"media/ldoce/hwd/ame/1/hernia.mp3"},"oxford":{"phon":"ˈhɜːniə","pos":"noun","senses":[{"en":"a medical condition in which part of an organ is pushed through a weak part in the muscle or tissue around it","cn":"疝；突出"}]}},"helmet":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"头盔;防护帽","en":"A helmet is a hat made of a strong material which you wear to protect your head."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a strong hard hat that soldiers, motorcycle riders, the police etc wear to protect their heads","cn":"头盔﹐钢盔﹐安全帽"}]},"collocations":{"phrases":["ADJ. visored | crash, cycle, flying, motorcycle, safety | fireman's, policeman's, etc.","VERB + HELMET have on, wear | put on | remove, take off"]},"media":{"img":["media/ldoce/img/motorcycle_helmet.jpg","media/thumb/helmet.jpg"],"uk":"media/ldoce/hwd/bre/f/helmet0205.mp3","us":"media/ldoce/hwd/ame/d/helmet.mp3"},"oxford":{"phon":"ˈhelmɪt","pos":"noun","senses":[{"en":"a type of hard hat that protects the head, worn, for example, by a police officer, a soldier or a person riding a bike or motorbike or playing some sports","cn":"头盔；防护帽","ex":{"en":"Police in riot helmets lined the streets.","cn":"戴着防暴头盔的警察站在沿街两边。"}}]}},"heroism":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"英雄气概;英雄主义;大无畏精神","en":"Heroism is great courage and bravery.","ex":{"en":"...individual acts of heroism.","cn":"个人英雄主义行为"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the quality of being brave when you are facing a difficult or dangerous situation, or when you are very ill","cn":""},{"en":"courage in a dangerous or frightening situation, especially when you are fighting in a war","cn":""},{"en":"the courage and determination to do something difficult or unpleasant","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"When you think of heroism , you might think of great acts of bravery, such as rushing into burning buildings and facing danger in battle. Heroism consists of putting others first, even at your own peril."}]},"collocations":{"phrases":["ADJ. great, real, true","PHRASES an act of heroism"]},"media":{"uk":"media/ldoce/hwd/bre/5/heroism0205.mp3","us":"media/ldoce/hwd/ame/e/laadheroism.mp3"},"examples":[{"en":"stories of heroism and self-sacrifice","cn":"关于英勇无畏和自我牺牲的故事"}],"oxford":{"phon":"ˈherəʊɪzəm","pos":"noun","senses":[{"en":"very great courage","cn":"英勇表现；英雄精神","ex":{"en":"The firefighters displayed both heroism and staunchness.","cn":"消防队员显示出英雄气概和不屈不挠的精神。"}}]}},"headline":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（尤指报纸头版的）标题，大字标题","en":"A headline is the title of a newspaper story, printed in large letters at the top of the story, especially on the front page.","ex":{"en":"The Daily Mail has the headline 'The Voice of Conscience'","cn":"《每日邮报》的头版标题为“良知的声音”。"}},{"pos":"N-PLURAL 复数名词","cn":"（广播或电视里的）新闻提要，简明新闻","en":"The headlines are the main points of the news which are read on radio or television.","ex":{"en":"I'm Claudia Polley with the news headlines.","cn":"我是克劳迪娅·波利，下面是新闻提要。"}},{"pos":"VERB 动词","cn":"标题为","en":"If a newspaper or magazine article is headlined a particular thing, that is the headline that introduces it.","ex":{"en":"The article was headlined 'Tell us the truth'.","cn":"文章题为“告诉我们真相”。"}},{"pos":"VERB 动词","cn":"在（演出）中担任主演","en":"If someone headlines a show, they are the main performer in it.","ex":{"en":"Sir Cliff Richard headlined the event.","cn":"克利夫·理查德爵士担任本次活动的主角。"}},{"pos":"PHRASE 短语","cn":"成为新闻焦点","en":"Someone or something that hits the headlines or grabs the headlines gets a lot of publicity from the media.","ex":{"en":"El Salvador first hit the world headlines at the beginning of the 1980s","cn":"萨尔瓦多在20世纪80年代初首次成为世人关注的新闻焦点。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"reports about recent events, reported in newspapers or on television, radio or the Internet","cn":""},{"en":"events that are reported in newspapers or in news programmes","cn":""},{"en":"a short news programme, in which only the most important pieces of news are read","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A headline is the title of a newspaper story. You'll know the headline , because it's printed in the largest font on the front of the paper."}]},"collocations":{"phrases":["ADJ. newspaper, tabloid &lsquo;Carnage at Airport&rsquo;, screamed the tabloid headline. | banner, front-page | screaming | lurid lurid head","VERB + HEADLINE carry, have, run The Guardian carried the front-page headline &lsquo;Drugs Firms Shamed&rsquo;. | read, scan, see I just had","HEADLINE + VERB proclaim sth, read sth, say sth, scream sth The Sunday Observer had a headline saying, &lsquo;Pop Star Arrested on Drugs Cha","HEADLINE + NOUN news &lsquo;Queen Mother goes on Holiday&rsquo; is hardly headline news!","PREP. in a/the ~ The most unusual fact in the story is often used in the headline. | under a/the ~ The Daily Gazette ran a story under the h","PHRASES make headline news The engagement of the two tennis stars made headline news. 2 the headlines: main news stories on TV/radio","ADJ. news","VERB + HEADLINE hear, listen to Let's just hear the news headlines. | look at, see, watch"]},"media":{"uk":"media/ldoce/hwd/bre/3/headline_n0205.mp3","us":"media/ldoce/hwd/ame/c/headline1.mp3"},"examples":[{"en":"They ran the story under the headline ‘Home at last!’.","cn":"报纸刊登这个报道的大标题为“终于回家了！”。"},{"en":"The scandal was in the headlines for several days.","cn":"这一丑闻连续几天都刊登在头版头条。"}],"oxford":{"phon":"ˈhedlaɪn","pos":"noun","senses":[{"en":"the title of a news article printed in large letters, especially at the top of the front page on a newspaper or the home page on a news website","cn":"（报纸或新闻网站首页的）大字标题","g":"[countable]","ex":{"en":"a newspaper headline","cn":"报纸大标题"}},{"en":"a short summary of the most important items of news, read at the beginning of a news programme on the radio or television","cn":"（电台或电视的）新闻摘要","g":"[plural]","ex":{"en":"Do you mind if I listen to the headlines before we leave?","cn":"你介意我在离开前听听头条新闻吗？"}},{"en":"to give a story or article a particular headline","cn":"给（报道、文章）加标题","g":"[transitive, usually passive]","ex":{"en":"The story was headlined ‘Back to the future’.","cn":"报道的标题是“回到未来”。"},"pos":"verb"},{"en":"to be the main performer in a concert or show","cn":"是（音乐会或演出的）主角","g":"[transitive, intransitive]","ex":{"en":"The concert is to be headlined by Ed Sheeran.","cn":"音乐会将由埃德·希兰主唱。"},"pos":"verb"},{"en":"particularly important","cn":"特别重要","ex":{"en":"The story was headline news for two weeks.","cn":"这个故事连续两周成为头条新闻。"},"pos":"adjective"},{"en":"used to describe the most important and popular performers at an entertainment event","cn":"用于描述娱乐活动中最重要和最受欢迎的表演者","ex":{"en":"The band were one of the headline acts at the music festival.","cn":"该乐队是音乐节上的主角之一。"},"pos":"adjective"}]}},"heave":{"collins":{"senses":[{"pos":"VERB 动词","cn":"（用力地）推，拉，拖，举起","en":"If you heave something heavy or difficult to move somewhere, you push, pull, or lift it using a lot of effort.","ex":{"en":"It took five strong men to heave the statue up a ramp and lower it into place","cn":"靠了5个强壮的男子才将雕像拉上坡道，再下放到合适的位置。"}},{"pos":"VERB 动词","cn":"（有节奏地）起伏","en":"If something heaves, it moves up and down with large regular movements.","ex":{"en":"His chest heaved, and he took a deep breath.","cn":"他的胸脯上下起伏，然后他深深地吸了口气。"}},{"pos":"VERB 动词","cn":"呕吐;恶心","en":"If you heave, or if your stomach heaves, you vomit or feel sick.","ex":{"en":"He gasped and heaved and vomited again","cn":"他又开始又喘又吐起来。"}},{"pos":"VERB 动词","cn":"深叹，长舒（一口气）","en":"If you heave a sigh, you give a big sigh.","ex":{"en":"Mr Collier heaved a sigh and got to his feet.","cn":"科利尔先生深叹一口气，站了起来。"}},{"pos":"VERB 动词","cn":"人头攒动;挤满（人）","en":"If a place is heaving or if it is heaving with people, it is full of people.","ex":{"en":"The Happy Bunny club was heaving","cn":"“快乐兔”俱乐部里人头攒动。"}},{"pos":"PHRASE 短语","cn":"出现;进入视野","en":"When something heaves into view or heaves into sight, it appears.","ex":{"en":"The train that now hove into view was clearly of a much older vintage.","cn":"现在进入视野的火车显然是一种古老得多的车型。"}},{"pos":"","cn":"","en":"to heave a sigh of relief→see: ;"},{"pos":"","cn":"","en":"相关词组：heave to"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make something or someone move in the direction that your hands are moving","cn":""},{"en":"to pull something suddenly with a short quick movement, often to get someone’s attention","cn":""},{"en":"to pull something along the ground, especially because it is heavy","cn":""}]},"vocab":{"pos":"1 v n 2 v n 3 v n 4 ","senses":[{"en":"When you heave something, you haul or lift a heavy object. You might not realize how fat your cat has become until you have to heave him out of the way to make room for yourself on the sofa."}]},"collocations":{"phrases":["ADJ. great, mighty","VERB + HEAVE give (sth) She gave a great heave and the box inched forward."]},"media":{"uk":"media/ldoce/hwd/bre/7/heave_n0205.mp3","us":"media/ldoce/hwd/ame/2/heave1.mp3"},"examples":[{"en":"With a mighty heave he lifted the sack onto the truck.","cn":"他用劲一举，把大麻袋扔到卡车上。"},{"en":"They heaved the body overboard.","cn":"他们使劲把尸体从船上抛入水中。"}],"oxford":{"phon":"hiːv","pos":"verb","senses":[{"en":"to lift, pull or throw somebody/something very heavy with one great effort","cn":"（用力）举起，拖，拉，抛","g":"[transitive, intransitive]","ex":{"en":"I managed to heave the trunk down the stairs.","cn":"我用力把箱子弄下楼梯。"}},{"en":"to rise up and down with strong, regular movements","cn":"（强烈而有节奏地）起伏","g":"[intransitive]","ex":{"en":"The boat heaved beneath them.","cn":"小船在他们脚下颠簸着。"}},{"en":"to make a sound slowly and often with effort","cn":"（常指吃力地）缓慢发出（声音）","g":"[transitive]","ex":{"en":"We all heaved a sigh of relief.","cn":"我们都如释重负地舒了一口气。"}},{"en":"to experience the tight feeling in your stomach that you get before you vomit","cn":"恶心","g":"[intransitive]","ex":{"en":"The thought of it makes me heave.","cn":"一想到那事我就恶心。"}},{"en":"an act of lifting, pulling or throwing","cn":"举；拖；拉；抛","g":"[countable]","ex":{"en":"With a mighty heave he lifted the sack onto the truck.","cn":"他用劲一举，把大麻袋扔到卡车上。"},"pos":"noun"},{"en":"a rising and falling movement","cn":"起伏","g":"[uncountable]","lab":"especially literary","ex":{"en":"the steady heave of the sea","cn":"大海汹涌不断的波涛"},"pos":"noun"}]}},"heroin":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"海洛因","en":"Heroin is a powerful drug which some people take for pleasure, but which they can become addicted to."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a powerful and illegal drug made from morphine","cn":"海洛因"}]},"collocations":{"phrases":["ADJ. pure | street","QUANT. dose, gram, ounce, shot, wrap","VERB + HEROIN fix, inject, smoke","HEROIN + NOUN injector | possession | injection | overdose a fatal heroin overdose | dealing • Note at DRUG (for more verbs and nouns)"]},"media":{"uk":"media/ldoce/hwd/bre/7/heroin0205.mp3","us":"media/ldoce/hwd/ame/f/heroin.mp3"},"examples":[{"en":"a heroin addict","cn":"吸海洛因上瘾的人"}],"oxford":{"phon":"ˈherəʊɪn","pos":"noun","senses":[{"en":"a powerful illegal drug made from morphine, that some people take for pleasure and can become addicted to","cn":"海洛因","ex":{"en":"a heroin addict","cn":"吸海洛因上瘾的人"}}]}},"hesitate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"犹豫;迟疑;踌躇","en":"If you hesitate, you do not speak or act for a short time, usually because you are uncertain, embarrassed, or worried about what you are going to say or do.","ex":{"en":"The telephone rang. Catherine hesitated, debating whether to answer it","cn":"电话响了。凯瑟琳犹豫了一下要不要去接。"}},{"pos":"VERB 动词","cn":"（因有顾虑而）不愿意（做某事）","en":"If you hesitate to do something, you delay doing it or are unwilling to do it, usually because you are not certain it would be right. If you do not hesitate to do something, you do it immediately.","ex":{"en":"Some parents hesitate to take these steps because they suspect that their child is exaggerating","cn":"一些家长不愿意采取这些措施，因为他们怀疑自己的孩子在夸大其词。"}},{"pos":"VERB 动词","cn":"尽管给我打电话/ 尽管和我们联系","en":"You can use hesitate in expressions such as 'don't hesitate to call me' or 'don't hesitate to contact us' when you are telling someone that they should do something as soon as it needs to be done and should not worry about disturbing other people.","ex":{"en":"In the event of difficulties, please do not hesitate to contact our Customer Service Department","cn":"如果遇到困难，请尽管和我们的客户服务部联系。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to stop speaking or stop doing something for a very short time before starting again. Pause is used especially in written descriptions. In everyday spoken English, people usually just say stop","cn":""},{"en":"to stop for a moment and wait before doing something, because you feel unsure or nervous about it","cn":""},{"en":"to stop working for a short time in order to rest, eat etc","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To hesitate is to pause before doing something, often out of concern or worry."}]},"collocations":{"phrases":["ADV. briefly, a little, (for) a minute/moment/second, momentarily Alison hesitated a moment, as if she were waiting for him.","VERB + HESITATE appear to, seem to | make sb Something about his smile made her hesitate.","PREP. about I didn't hesitate about working with Craig. | between He was hesitating between a glass of wine and an orange juice. | over He s"]},"media":{"uk":"media/ldoce/hwd/bre/5/hesitate0205.mp3","us":"media/ldoce/hwd/ame/5/hesitate.mp3"},"examples":[{"en":"I have no hesitation in recommending her for the job.","cn":"我毫不犹豫地推荐她做这项工作。"},{"en":"I didn't hesitate for a moment about taking the job.","cn":"我毫不犹豫地接受了那份工作。"}],"oxford":{"phon":"ˈhezɪteɪt","pos":"verb","senses":[{"en":"to be slow to speak or act because you feel uncertain or nervous","cn":"（对某事）犹豫，迟疑不决","g":"[intransitive, transitive]","ex":{"en":"She hesitated before replying.","cn":"她犹豫了一下才回答。"}},{"en":"to be worried about doing something, especially because you are not sure that it is right or appropriate","cn":"顾虑；疑虑","g":"[intransitive]","ex":{"en":"Please do not hesitate to contact me if you have any queries.","cn":"如果有疑问就请尽管和我联系。"}}]}},"heroic":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"英雄的;英勇的","en":"If you describe a person or their actions as heroic, you admire them because they show extreme bravery.","ex":{"en":"The heroic sergeant risked his life to rescue 29 fishermen from their blazing trawler","cn":"英勇的中士冒着生命危险从熊熊燃烧着的拖网渔船上救出了29名渔民。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"矢志不渝的;艰苦卓绝的","en":"If you describe an action or event as heroic, you admire it because it involves great effort or determination to succeed.","ex":{"en":"The company has made heroic efforts at cost reduction","cn":"公司在降低成本方面付出了艰苦卓绝的努力。"}},{"pos":"ADJ 形容词","cn":"男主角的","en":"Heroic means being or relating to the hero of a story.","ex":{"en":"...the book's central, heroic figure.","cn":"书中的中心主角人物"}},{"pos":"N-PLURAL 复数名词","cn":"英雄壮举;英勇果断的行为","en":"Heroics are actions involving bravery, courage, or determination.","ex":{"en":"...the man whose aerial heroics helped save the helicopter pilot","cn":"以空中的英雄壮举拯救了直升机飞行员的人"}},{"pos":"N-PLURAL 复数名词","cn":"（愚蠢或危险的）逞英雄行为","en":"If you describe someone's actions or plans as heroics, you think that they are foolish or dangerous because they are too difficult or brave for the situation in which they occur.","ex":{"en":"He said his advice was: 'No heroics, stay within the law'","cn":"他说自己的建议是：“不要逞英雄，要遵纪守法。”"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"showing that you are not afraid to do things that other people find dangerous or difficult","cn":""},{"en":"very brave – used especially about someone fighting for what they believe in, or fighting against a disease","cn":""},{"en":"brave and willing to take a lot of risks","cn":""}]},"vocab":{"pos":"1 adj 2 adj n","senses":[{"en":"Heroic means having the qualities of a hero, such as bravery. Maybe on your daily walk, you see a house on fire, and you run into the flames repeatedly to save the family and their pets, including the fish! That’s heroic ."}]},"collocations":{"phrases":["VERBS be","ADV. truly a truly heroic battle | suitably He struck a suitably heroic pose."]},"media":{"uk":"media/ldoce/hwd/bre/e/heroic0205.mp3","us":"media/ldoce/hwd/ame/9/heroic.mp3"},"examples":[{"en":"We watched our team's heroic struggle to win back the cup.","cn":"我们目睹了我队为赢回奖杯所付出的不懈努力。"},{"en":"Rescuers made heroic efforts to save the crew.","cn":"救援人员不畏艰险努力营救全体船员。"}],"oxford":{"phon":"həˈrəʊɪk","pos":"adjective","senses":[{"en":"showing extreme courage and admired by many people","cn":"英勇的；英雄的","ex":{"en":"She is a heroic figure we can all look up to.","cn":"她是我们都会敬仰的英雄人物。"}},{"en":"showing a determined effort to succeed or to achieve something, especially something difficult","cn":"有必胜决心的；不畏艰难的","ex":{"en":"We watched our team's heroic struggle to win back the cup.","cn":"我们目睹了我队为赢回奖杯所付出的不懈努力。"}},{"en":"that is about or involves a hero","cn":"（关于）英雄的","ex":{"en":"a heroic story/poem","cn":"英雄故事／颂诗"}},{"en":"very large or great","cn":"巨大的；了不起的","ex":{"en":"This was foolishness on a heroic scale.","cn":"这简直是天大的蠢事。"}}]}},"heighten":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（使）（情感）增强;（使）加深","en":"If something heightens a feeling or if the feeling heightens, the feeling increases in degree or intensity.","ex":{"en":"The move has heightened tension in the state","cn":"该举动加剧了州里的紧张气氛。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make something such as someone's determination or belief increase so that it is even stronger than it was before","cn":""},{"en":"if something heightens knowledge, fears, the effect of something etc, it makes it increase so that it is felt more strongly","cn":""},{"en":"to increase a feeling or problem, so that it becomes worse","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"When you heighten something, you increase it or make it more intense. If you want to heighten awareness about homelessness, you might write an article for your local newspaper."}]},"collocations":{"phrases":["ADV. greatly This latest attack has greatly heightened fears of an all-out war. | further","VERB + HEIGHTEN serve to Seeing others enjoying themselves only served to heighten his sense of loneliness. | seek to an exercise which seek"]},"media":{"uk":"media/ldoce/hwd/bre/c/heighten0205.mp3","us":"media/ldoce/hwd/ame/1/heighten.mp3"},"examples":[{"en":"The campaign is intended to heighten public awareness of the disease.","cn":"这场运动的目的是使公众更加了解这种疾病。"},{"en":"Tension has heightened after the recent bomb attack.","cn":"最近的炸弹袭击之后，情势更加紧张。"}],"oxford":{"phon":"ˈhaɪtn","pos":"verb","senses":[{"en":"if a feeling or an effect heightens, or something heightens it, it becomes stronger or increases","cn":"（使）加强，提高，增加","ex":{"en":"Tension has heightened after the recent bomb attack.","cn":"最近的炸弹袭击之后，情势更加紧张。"}}]}},"heartbeat":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"心搏;心跳","en":"Your heartbeat is the regular movement of your heart as it pumps blood around your body.","ex":{"en":"Your baby's heartbeat will be monitored continuously.","cn":"宝宝的心搏将会受到持续监控。"}},{"pos":"N-COUNT 可数名词","cn":"（一次）心搏，心跳","en":"A heartbeat is one of the movements of your heart.","ex":{"en":"Smoking could lead to irregular heartbeats.","cn":"吸烟会引起心律失常。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the action or sound of your heart as it pumps blood through your body","cn":"心跳﹐心搏"},{"en":"to be very close to a situation or position 〔","cn":"状态或位置〕非常接近某事物"},{"en":"very quickly, without delay","cn":"一下子"}]},"collocations":{"phrases":["ADJ. irregular, regular | racing She was suddenly aware of her racing heartbeat.","VERB + HEARTBEAT monitor | feel","PHRASES the sound/thud of a heartbeat I could feel the thud of my heartbeat."]},"media":{"uk":"media/ldoce/hwd/bre/0/heartbeat0205.mp3","us":"media/ldoce/hwd/ame/a/heartbeat.mp3"},"examples":[{"en":"The candidate said that he understood the heartbeat of the Hispanic community in California.","cn":"这位候选人说他了解加利福尼亚州的西班牙语裔美国人社区的特点。"},{"en":"If I was offered another job, I'd leave in a heartbeat.","cn":"如果能找到另外一份工作，我马上就走。"}],"oxford":{"phon":"ˈhɑːtbiːt","pos":"noun","senses":[{"en":"the movement or sound of the heart as it sends blood around the body","cn":"心跳；心搏；心跳声","g":"[countable, uncountable]","ex":{"en":"a rapid/regular heartbeat","cn":"急速／正常的心跳"}},{"en":"an important feature of something, that is responsible for making it what it is","cn":"重要特征；中心","g":"[singular]","ex":{"en":"The candidate said that he understood the heartbeat of the Hispanic community in California.","cn":"这位候选人说他了解加利福尼亚州的拉美裔美国人社区的特点。"}}]}},"heaven":{"collins":{"senses":[{"pos":"N-PROPER 专有名词","cn":"天堂;天国","en":"In some religions, heaven is said to be the place where God lives, where good people go when they die, and where everyone is always happy. It is usually imagined as being high up in the sky.","ex":{"en":"I believed that when I died I would go to heaven and see God.","cn":"我相信自己死后会升入天堂，见到上帝。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"极乐（之地）；天堂般美好（的世界）","en":"You can use heaven to refer to a place or situation that you like very much.","ex":{"en":"We went touring in Wales and Ireland. It was heaven","cn":"我们去了威尔士和爱尔兰旅游。那里真是人间仙境。"}},{"pos":"N-PLURAL 复数名词","cn":"天空","en":"The heavens are the sky.","ex":{"en":"He walked out into the middle of the road, looking up at the heavens.","cn":"他走出去站在大路中间，抬头仰望着天空。"}},{"pos":"PHRASE 短语","cn":"但愿不会这样;千万不要这样;苍天不容;老天不许","en":"You say 'Heaven forbid!' to emphasize that you very much hope that something will not happen.","ex":{"en":"Heaven forbid that he should leave because of me!","cn":"但愿他不会因为我而离开！"}},{"pos":"EXCLAM 感叹语","cn":"（表示惊讶或强调）天哪","en":"You say 'Good heavens!' or 'Heavens!' to express surprise or to emphasize that you agree or disagree with someone.","ex":{"en":"Good Heavens! That explains a lot!","cn":"天哪！这下我明白了！"}},{"pos":"PHRASE 短语","cn":"…只有靠天帮忙了;谁也帮不了…了","en":"You say 'Heaven help someone' when you are worried that something bad is going to happen to them, often because you disapprove of what they are doing or the way they are behaving.","ex":{"en":"If this makes sense to our leaders, then heaven help us all","cn":"如果我们的领导人认为这是合情合理的，那么谁也帮不了我们了。"}},{"pos":"PHRASE 短语","cn":"天知道;谁晓得","en":"You can say 'Heaven knows' to emphasize that you do not know something, or that you find something very surprising.","ex":{"en":"Heaven knows what they put in it.","cn":"天知道他们在里面放了些什么。"}},{"pos":"PHRASE 短语","cn":"确实;一定;无疑","en":"You can say 'Heaven knows' to emphasize something that you feel or believe very strongly.","ex":{"en":"Heaven knows they have enough money","cn":"他们的钱够多了。"}},{"pos":"PHRASE 短语","cn":"想尽一切办法;竭尽全力;千方百计","en":"If you move heaven and earth to do something, you try as hard as you can to do it.","ex":{"en":"They would move heaven and earth to stop me if they could.","cn":"可能的话，他们会千方百计地阻止我。"}},{"pos":"PHRASE 短语","cn":"（用于以 what、when、who、why 及 how 开头的疑问句中表示强调）到底，究竟","en":"You can use in heaven's name in questions beginning with 'what', 'when', 'who', 'why' and 'how' to add emphasis in a way that shows that you are very angry or surprised.","ex":{"en":"Where in heaven's name was she?","cn":"她到底在哪儿？"}},{"pos":"PHRASE 短语","cn":"突然下起倾盆大雨","en":"If the heavens open, it suddenly starts raining very heavily.","ex":{"en":"The match had just begun when the heavens opened and play was suspended.","cn":"比赛刚刚开始就突然下起倾盆大雨，所以只好暂停了。"}},{"pos":"","cn":"","en":"for heaven's sake→see: ; thank heavens→see: ;"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"say this when you hope that what has just been mentioned will not happen or is not true","cn":""},{"en":"use this to say very strongly that you hope something does not happen or has not happened","cn":""},{"en":"say this when you mean that it is impossible to know something","cn":""}]},"collocations":{"phrases":["VERB + HEAVEN ascend to, go to I feel like I've died and gone to heaven.","PREP. from ~ Our child seemed a gift from heaven. | in ~ (figurative) It was a marriage made in heaven.","PHRASES the kingdom of heaven 2 place/situation in which you are very happy","ADJ. absolute, sheer It was sheer heaven being alone at last.","PREP. in ~ The kids were in absolute heaven at the fair.","PHRASES a heaven on earth The island is truly a heaven on earth. | sb's idea of heaven Building up a tan by the pool with a good book is my "]},"media":{"uk":"media/ldoce/hwd/bre/d/heaven0205.mp3","us":"media/ldoce/hwd/ame/7/heaven1.mp3"},"examples":[{"en":"I feel like I've died and gone to heaven.","cn":"我彷佛觉得自己已经死了，进了天堂。"},{"en":"It was heaven being away from the office for a week.","cn":"一个星期远离办公室真是快活极了。"}],"oxford":{"phon":"ˈhevn","pos":"noun","senses":[{"en":"the place believed to be the home of God where good people go when they die, sometimes imagined to be in the sky","cn":"天堂；天国","g":"[uncountable]","ex":{"en":"the kingdom of heaven","cn":"天国"}},{"en":"a place or situation in which you are very happy","cn":"极乐之地；极乐","g":"[uncountable, countable]","lab":"informal","ex":{"en":"This isn't exactly my idea of heaven!","cn":"这可不太像我所想象的那么美妙！"}},{"en":"the sky","cn":"天空","g":"[plural]","lab":"literary","ex":{"en":"Four tall trees stretched up to the heavens.","cn":"四棵大树参天而立。"}}]}},"headache":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"头痛","en":"If you have a headache, you have a pain in your head.","ex":{"en":"I have had a terrible headache for the last two days.","cn":"两天来我一直头痛得厉害。"}},{"pos":"N-COUNT 可数名词","cn":"使人头痛的事;棘手的事;难题","en":"If you say that something is a headache, you mean that it causes you difficulty or worry.","ex":{"en":"The airline's biggest headache is the increase in the price of aviation fuel","cn":"令航空公司最头痛的事就是航空燃料价格的上涨。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a pain in your head","cn":"头痛"},{"en":"a headache and feeling of sickness that you get the day after you have drunk too much alcohol","cn":"宿醉"},{"en":"a very bad headache, which makes you feel sick and have difficulty seeing","cn":"偏头痛"}]},"vocab":{"pos":"n","senses":[{"en":"A headache is a pain or ache in your head, especially one that lasts longer than a few minutes. You might get a headache after a day of staring at a computer screen."}]},"collocations":{"phrases":["ADJ. bad, severe, terrible, violent | mild, slight | dull | pounding, splitting, throbbing | migraine, tension He developed a sever e migrai","VERB + HEADACHE have, suffer from I've got a splitting headache. | get, develop We all get headaches from time to time. | complain of The wo","HEADACHE + NOUN pill, tablet •","ADJ. big, major, real | constant","PREP. ~ for Uneven cash flo w proved to be a major headache for the company."]},"media":{"uk":"media/ldoce/hwd/bre/d/headache0205.mp3","us":"media/ldoce/hwd/ame/f/headache.mp3"},"examples":[{"en":"The real headache will be getting the bank to lend you the money.","cn":"真正的麻烦将是设法让银行贷款给你。"},{"en":"Red wine gives me a headache.","cn":"我喝红酒会头痛。"}],"oxford":{"phon":"ˈhedeɪk","pos":"noun","senses":[{"en":"a continuous pain in the head","cn":"头痛","lab":"British English","ex":{"en":"He had a terrible headache.","cn":"他头痛得厉害。"}},{"en":"a person or thing that causes worry or trouble","cn":"令人头痛的人（或事物）；麻烦","lab":"informal","ex":{"en":"The real headache will be getting the bank to lend you the money.","cn":"真正的麻烦将是设法让银行贷款给你。"}}]}},"hepatitis":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"肝炎","en":"Hepatitis is a serious disease which affects the liver."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a disease of the liver that causes fever and makes your skin yellow. There are several types of hepatitis: hepatitis A, which is less severe, and hepatitis B and C, which are much more serious.","cn":"肝炎"}]},"collocations":{"phrases":["ADJ. severe | acute, chronic | active | viral","VERB + HEPATITIS have, suffer from | be infected with, contract, get","HEPATITIS + NOUN virus | patient","PHRASES hepatitis A/B/C •"]},"media":{"uk":"media/ldoce/hwd/bre/e/hepatitis0205.mp3","us":"media/ldoce/hwd/ame/f/hepatitis.mp3"},"oxford":{"phon":"ˌhepəˈtaɪtɪs","pos":"noun","senses":[{"en":"a serious disease of the liver. There are three main forms: hepatitis A, the least serious, caused by infected food (= containing harmful bacteria), and hepatitis B and hepatitis C, both very serious and caused by infected blood.","cn":"肝炎","ex":{"en":"Have you had your hepatitis B vaccination?","cn":"你接种过乙肝疫苗吗？"}}]}},"herring":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"鲱（鱼）","en":"A herring is a long silver-coloured fish. Herring live in large groups in the sea."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long thin silver sea fish that can be eaten","cn":"鲱鱼"}]},"collocations":{"phrases":["ADJ. fresh | pickled, salted, smoked, soused","VERB + HERRING catch | eat, have","HERRING + NOUN fillet •"]},"media":{"uk":"media/ldoce/hwd/bre/6/brelasdeherring.mp3","us":"media/ldoce/hwd/ame/9/herring.mp3"},"examples":[{"en":"fresh herring fillets","cn":"新鲜鲱鱼片"},{"en":"pickled herrings","cn":"腌制的鲱鱼"}],"oxford":{"phon":"ˈherɪŋ","pos":"noun","senses":[{"en":"a N Atlantic fish that swims in very large groups and is used for food","cn":"鲱鱼（产于北大西洋，成大群游动，可食）","ex":{"en":"shoals of herring","cn":"鲱鱼群"}}]}},"heirloom":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"祖传遗物;传家宝","en":"An heirloom is an ornament or other object that has belonged to a family for a very long time and that has been handed down from one generation to another."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a valuable object that has been owned by a family for many years and that is passed from the older members to the younger members","cn":"传家宝﹐祖传之宝"},{"en":"an heirloom vegetable or plant is one of a kind that was first grown many years ago, and has now become rare or unusual 〔","cn":"蔬菜或植物〕珍稀的﹐不常见的"}]},"vocab":{"pos":"n","senses":[{"en":"An heirloom is something passed down in a family for generations. Your grandma's prized necklace could be an heirloom ."}]},"collocations":{"phrases":["ADJ. family | ancient","HEIRLOOM + VERB be passed down, come down The brooch is a family heirloom which came down to her from her great-grandmother."]},"media":{"uk":"media/ldoce/hwd/bre/c/heirloom0205.mp3","us":"media/ldoce/hwd/ame/7/heirloom.mp3"},"examples":[{"en":"a family heirloom","cn":"传家宝"},{"en":"They sell many kinds of heirloom seeds.","cn":"他们出售各种稀有种子。"}],"oxford":{"phon":"ˈeəluːm","pos":"noun","senses":[{"en":"a valuable object that has belonged to the same family for many years","cn":"传家宝；世代相传之物","ex":{"en":"a family heirloom","cn":"传家宝"}},{"en":"heirloom plants are varieties that were commonly grown in the past but are no longer grown as commercial crops","cn":"（植物）原种的（指过去很常见，但如今已不再作为经济作物而种植的品种）","pos":"adjective"}]}},"herb":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（调味或药用的）芳草;香草;药草","en":"A herb is a plant whose leaves are used in cooking to add flavour to food, or as a medicine."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a living thing that has leaves and roots and grows in earth, especially one that is smaller than a tree","cn":""},{"en":"a small plant that is used to improve the taste of food, or to make medicine","cn":"香草﹔药草"},{"en":"a wild plant growing where it is not wanted that prevents crops or garden flowers from growing properly","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"What do food, medicine, and perfume have in common? Well, they all can be created from herbs . An herb is a plant that has a soft rather than a woody stem, and it tends to have a unique taste or smell."}]},"collocations":{"phrases":["ADJ. dried, fresh | mixed Add a teaspoonful of mixed herbs. | aromatic, fragrant | culinary, medicinal","QUANT. bunch","VERB + HERB garnish sth with Serve cold, garnished with fresh herbs.","HERB + NOUN bed, border, garden •"]},"media":{"uk":"media/ldoce/hwd/bre/e/herb0205.mp3","us":"media/ldoce/hwd/ame/5/herb.mp3"},"examples":[{"en":"( NAmE ) an herb garden","cn":"芳草园"},{"en":"a herb garden","cn":"芳草园"}],"oxford":{"phon":"hɜːb","pos":"noun","senses":[{"en":"a plant whose leaves, flowers or seeds are used to add taste to food, in medicines or for their pleasant smell. parsley, mint and oregano are all herbs.","cn":"药草；香草","lab":"North American English","ex":{"en":"a herb garden","cn":"芳草园"}},{"en":"a plant with a soft stem that dies down after flowering","cn":"草本","lab":"specialist"},{"en":"a first name for boys, short for Herbert","cn":"赫布（男子名，Herbert缩写）","pos":""}]}},"heap":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（尤指杂乱的）一堆","en":"A heap of things is a pile of them, especially a pile arranged in a rather untidy way.","ex":{"en":"...a heap of bricks","cn":"一堆砖"}},{"pos":"VERB 动词","cn":"堆放;堆积;堆起","en":"If you heap things somewhere, you arrange them in a large pile.","ex":{"en":"Mrs. Madrigal heaped more carrots onto Michael's plate.","cn":"马德里加尔夫人将更多的胡萝卜堆到了迈克尔的盘子里。"}},{"pos":"VERB 动词","cn":"（对…）极力（赞扬或批评）","en":"If you heap praise or criticism on someone or something, you give them a lot of praise or criticism.","ex":{"en":"The head of the navy heaped scorn on both the methods and motives of the conspirators.","cn":"海军首长对密谋分子的手法和动机都表示出极大的轻蔑。"}},{"pos":"QUANT 数量词","cn":"大量;许多","en":"Heaps of something or a heap of something is a large quantity of it.","ex":{"en":"You have heaps of time","cn":"你有的是时间。"}},{"pos":"PHRASE 短语","cn":"身处底层/身处高层","en":"Someone who is at the bottom of the heap or at the top of the heap is low down or high up in society or an organization.","ex":{"en":"...those at the top of the social heap","cn":"那些身处社会高层的人们"}},{"pos":"PHRASE 短语","cn":"颓然（倒下）；重重地（倒下）","en":"If someone collapses in a heap, they fall heavily and untidily and do not move.","ex":{"en":"The young footballer collapsed in a heap after a heavy tackle.","cn":"年青的足球队员完成激烈的阻截后瘫倒在地动弹不得。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a group of things of the same type that are put on top of each other","cn":""},{"en":"a neat pile of things of the same type","cn":""},{"en":"a large messy pile of things","cn":""}]},"vocab":{"pos":"1 n v 2 n","senses":[{"en":"A great big pile of something is a heap . Your sloppy brother might keep all of his clothes in a heap on his bedroom floor."}]},"collocations":{"phrases":["ADJ. big, great, large | little, small | crumpled, untidy | compost, manure, muck, rubbish, scrap, slag, spoil colliery spoil heaps","VERB + HEAP be piled in Papers were piled in great heaps on the desk. | collapse in, fall (down) in (both figurative) He collapsed in an exh","PREP. in a/the ~ His clothes lay in a crumpled heap on the floor. | on/onto a/the ~ Throw the potato peelings on the compost heap. | ~ of a ","PHRASES the bottom/top of the heap (figurative) These workers are at the bottom of the economic heap."]},"media":{"uk":"media/ldoce/hwd/bre/9/heap_n0205.mp3","us":"media/ldoce/hwd/ame/9/heap1.mp3"},"examples":[{"en":"He looks heaps better than when I last saw him.","cn":"他看上去比我上回见他时好多了。"},{"en":"These workers are at the bottom of the economic heap.","cn":"这些工人处在经济结构的底层。"}],"oxford":{"phon":"hiːp","pos":"noun","senses":[{"en":"an untidy pile of something","cn":"（凌乱的）一堆","ex":{"en":"The building was reduced to a heap of rubble.","cn":"大楼变成了一堆废墟。"}},{"en":"a lot of something","cn":"大量；许多","g":"[usually plural]","lab":"informal","ex":{"en":"There's heaps of time before the plane leaves.","cn":"离飞机起飞还有很多时间。"}},{"en":"a car that is old and in bad condition","cn":"破旧的汽车；老爷车","lab":"informal, humorous，，"},{"en":"to put things in an untidy pile","cn":"堆积（东西）；堆置","ex":{"en":"Rocks were heaped up on the side of the road.","cn":"路边堆积着石头。"},"pos":"verb"},{"en":"to put a lot of something in a pile on something","cn":"在…上放很多（东西）","ex":{"en":"She heaped food on my plate.","cn":"她往我的盘子里放了很多食物。"},"pos":"verb"},{"en":"to give a lot of something such as praise or criticism to somebody","cn":"对（某人）大加赞扬（或批评等）","ex":{"en":"He heaped praise on his team.","cn":"他高度赞扬了他的队。"},"pos":"verb"}]}},"heater":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"加热器;加热装置;暖气设备;炉子","en":"A heater is a piece of equipment or a machine which is used to raise the temperature of something, especially of the air inside a room or a car.","ex":{"en":"There's an electric heater in the bedroom.","cn":"卧室里有个电暖器。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a machine for making air or water hotter","cn":"加热器﹔暖气机﹔暖炉"}]},"collocations":{"phrases":["ADJ. convector, fan, immersion, instantaneous, multi-point, storage | electric, gas, oil, paraffin | aquarium, car, greenhouse, pool, room, ","VERB + HEATER have off/on | turn off/on | turn down/up","HEATER + VERB be off/on Even with the heater full on, the room felt cold."]},"media":{"uk":"media/ldoce/hwd/bre/e/heater0205.mp3","us":"media/ldoce/hwd/ame/7/heater.mp3"},"examples":[{"en":"a gas heater","cn":"煤气炉"},{"en":"a water heater","cn":"热水器"}],"oxford":{"phon":"ˈhiːtə(r)","pos":"noun","senses":[{"en":"a machine used for making air or water warmer","cn":"加热器；炉子；热水器","ex":{"en":"a gas heater","cn":"煤气炉"}}]}},"heroine":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（书、戏剧、电影或故事中品行端正的）女主角，女主人公","en":"The heroine of a book, play, film, or story is the main female character, who usually has good qualities.","ex":{"en":"The heroine is a senior TV executive.","cn":"女主角是一名电视台的高级主管。"}},{"pos":"N-COUNT 可数名词","cn":"女英雄;女杰;女豪杰","en":"A heroine is a woman who has done something brave, new, or good, and who is therefore greatly admired by a lot of people.","ex":{"en":"The national heroine of the day was Xing Fen, winner of the first Gold medal of the Games.","cn":"现今的民族英雄是在该运动会上获得首枚金牌的邢芬。"}},{"pos":"N-COUNT 可数名词","cn":"（女）偶像;心目中的女英雄","en":"If you describe a woman as your heroine, you mean that you admire her greatly, usually because of a particular quality or skill that she has.","ex":{"en":"My heroine was Elizabeth Taylor.","cn":"我心目中的偶像是伊丽莎白·泰勒。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who you admire very much because of what they have done. Use hero about a man, use heroine about a woman","cn":""},{"en":"a famous actor, actress, musician, or sports player that a lot of people admire","cn":""},{"en":"a person in a story","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A heroine is a real-life or fictional woman who has lots of courage and fights on the side of good, maybe by rescuing a kitten from a tree, slaying an evil dragon, or helping you with your science fair project."}]},"collocations":{"phrases":["ADJ. great Violetta is one of the great tragic heroines of Verdi's operas. | national | romantic, tragic | unsung She remains one of the uns"]},"media":{"uk":"media/ldoce/hwd/bre/7/heroin0205.mp3","us":"media/ldoce/hwd/ame/f/heroin.mp3"},"examples":[{"en":"The heroine is played by Demi Moore.","cn":"女主角由黛米 · 穆尔扮演。"},{"en":"Madonna was her teenage heroine.","cn":"麦当娜是她十几岁时的偶像。"}],"oxford":{"phon":"ˈherəʊɪn","pos":"noun","senses":[{"en":"a girl or woman who is admired by many for doing something brave or good","cn":"女英雄；女豪杰","ex":{"en":"the heroines of the revolution","cn":"那场革命中的各位女英雄"}},{"en":"the main female character in a story, novel, film, etc.","cn":"（故事、小说、电影等中的）女主人公，女主角","ex":{"en":"The heroine is played by Demi Moore.","cn":"女主角由黛米·摩尔扮演。"}},{"en":"a woman that you admire because of a particular quality or skill that she has","cn":"崇拜的女人；女偶像","ex":{"en":"Madonna was her teenage heroine.","cn":"麦当娜是她十几岁时的偶像。"}}]}},"hesitation":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"犹豫;疑虑;不情愿","en":"Hesitation is an unwillingness to do something, or a delay in doing it, because you are uncertain, worried, or embarrassed about it.","ex":{"en":"He promised there would be no more hesitations in pursuing reforms.","cn":"他答应在推进改革这件事上不再迟疑不决。"}},{"pos":"PHRASE 短语","cn":"毫不犹豫","en":"If you say that you have no hesitation in doing something, you are emphasizing that you will do it immediately or willingly because you are certain that it is the right thing to do.","ex":{"en":"The board said it had no hesitation in unanimously rejecting the offer","cn":"董事会自称毫不犹豫地一致否决了该项报价。"}},{"pos":"PHRASE 短语","cn":"毫不犹豫地;心甘情愿地","en":"If you say that someone does something without hesitation, you are emphasizing that they do it immediately and willingly.","ex":{"en":"The great majority of players would, of course, sign the contract without hesitation","cn":"绝大多数球员当然会毫不犹豫地签合同。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when someone hesitates","cn":"犹豫﹐踌躇﹐迟疑"}]},"vocab":{"pos":"n","senses":[{"en":"A hesitation is a pause. If your friend asks you, \"Do I look fat in this dress?\" you'd better make sure there's not a second's hesitation before you answer, \"No, not at all!\""}]},"collocations":{"phrases":["ADJ. brief, fractional, momentary, slight There was a momentary hesitation before he replied. | initial After some initial hesitation, teach","PREP. after &hellip; ~ After much hesitation, they decided to leave. | without ~ She answered immediately, without any hesitation.","PHRASES have no hesitation in doing sth I have no hesitation in recommending him for the job. | a moment's hesitation, a moment of hesitatio"]},"media":{"uk":"media/ldoce/hwd/bre/3/hesitation0205.mp3","us":"media/ldoce/hwd/ame/c/hesitation.mp3"},"examples":[{"en":"I have no hesitation in recommending her for the job.","cn":"我毫不犹豫地推荐她做这项工作。"},{"en":"He spoke fluently and without unnecessary hesitations.","cn":"他说得很流畅，毫不支吾。"}],"oxford":{"phon":"ˌhezɪˈteɪʃn","pos":"noun","senses":[{"en":"the act of being slow to speak or act because you feel uncertain or nervous","cn":"（对某事）犹豫，迟疑不决","g":"[uncountable, countable]","ex":{"en":"She agreed without the slightest hesitation.","cn":"她毫不犹豫地同意了。"}},{"en":"the fact of being worried about doing something, especially because you are not sure that it is right or appropriate","cn":"顾虑；疑虑","g":"[uncountable]","ex":{"en":"I have no hesitation in recommending her for the job.","cn":"我毫不犹豫地推荐她做这项工作。"}}]}},"heartland":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（某活动或信仰占优势的）中心区域，核心地区","en":"Journalists use heartland or heartlands to refer to the area or region where a particular set of activities or beliefs is most significant.","ex":{"en":"...his six-day bus tour around the industrial heartland of America","cn":"他在美国工业中心区域的大巴6日游"}},{"pos":"N-COUNT 可数名词","cn":"（国家或大陆的）心脏地带，腹地","en":"The most central area of a country or continent can be referred to as its heartland or heartlands.","ex":{"en":"We then headed west towards the heartland of Poland","cn":"我们随后朝西前往波兰中部。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the central part of a country or area of land","cn":"中心区域"},{"en":"the most important part of a country or area for a particular activity, or the part where a political group has most support 〔","cn":"国家或地区的〕心脏地带﹐最重要地区﹔〔某政党占优势的〕根据地﹐大本营"}]},"collocations":{"phrases":["ADJ. agricultural, industrial the industrial heartland of Germany | Conservative, Labour, etc. | traditional","PREP. in a/the ~ The party has lost seats in its traditional heartland of southern Thailand."]},"media":{"uk":"media/ldoce/hwd/bre/b/heartland0205.mp3","us":"media/ldoce/hwd/ame/6/heartland.mp3"},"examples":[{"en":"the traditional Tory heartland of Britain's boardrooms","cn":"保守党的传统领地：英国的各董事会"},{"en":"the great Russian heartlands","cn":"广袤的俄罗斯中心地带"}],"oxford":{"phon":"ˈhɑːtlænd","pos":"noun","senses":[{"en":"the central part of a country or an area","cn":"（国家或地区的）腹地，中心区域","ex":{"en":"the great Russian heartlands","cn":"广袤的俄罗斯中心地带"}},{"en":"an area that is important for a particular activity or political party","cn":"（活动或政党的）重要场所，核心区域","ex":{"en":"the industrial heartland of Germany","cn":"德国的工业中心区"}}]}},"herd":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"兽群;畜群","en":"A herd is a large group of animals of one kind that live together.","ex":{"en":"...large herds of elephant and buffalo.","cn":"大群的大象和水牛"}},{"pos":"N-SING 单数名词","cn":"（缺乏独立思想的）一般民众，芸芸众生","en":"If you say that someone has joined the herd or follows the herd, you are criticizing them because you think that they behave just like everyone else and do not think for themselves.","ex":{"en":"They are individuals; they will not follow the herd.","cn":"他们是独立的个体，不愿随大溜。"}},{"pos":"VERB 动词","cn":"使集在一起;把…赶在一起","en":"If you herd people somewhere, you make them move there in a group.","ex":{"en":"He began to herd the prisoners out","cn":"他开始将犯人集中在一起赶出来。"}},{"pos":"VERB 动词","cn":"驱赶，牧放（畜群）","en":"If you herd animals, you make them move along as a group.","ex":{"en":"Stefano used a motor cycle to herd the sheep","cn":"斯特凡诺骑一辆摩托车放羊。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a group of cows, deer, or elephants","cn":""},{"en":"a group of animals that work together","cn":""},{"en":"a group of sheep or birds","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A herd is a bunch of animals, or — people who act like a bunch of animals. It's also a verb — when people herd animals, they try to keep them moving in the same direction."}]},"collocations":{"phrases":["ADJ. great, large | small | beef, breeding, dairy The farm has only a small dairy herd. | cattle, elephant, etc.","HERD + NOUN instinct","PREP. in a/the ~ The animals tend to graze in a herd. | ~ of a large herd of cows","PHRASES a member of a herd 2 group of people","ADJ. common","VERB + HERD follow If you feel so strongly, why follow the herd (= do the same as everybody else) ? | stand out from She prided herself on s","HERD + NOUN instinct"]},"media":{"uk":"media/ldoce/hwd/bre/a/herd_n0205.mp3","us":"media/ldoce/hwd/ame/a/herd1.mp3"},"examples":[{"en":"She pushed her way through a herd of lunchtime drinkers.","cn":"她从一群午餐时饮酒的人中间挤了过去。"},{"en":"They were herded together into trucks and driven away.","cn":"他们被一起赶上卡车拉走了。"}],"oxford":{"phon":"hɜːd","pos":"noun","senses":[{"en":"a group of animals of the same type that live and feed together","cn":"兽群；牧群","ex":{"en":"a herd of cows/deer/elephants","cn":"一群牛／鹿／象"}},{"en":"a large group of people of the same type","cn":"人群；芸芸众生","lab":"usually disapproving","ex":{"en":"She pushed her way through a herd of lunchtime drinkers.","cn":"她从一群午餐时饮酒的人中间挤了过去。"}},{"en":"to move or make somebody/something move in a particular direction","cn":"（使）向…移动","g":"[intransitive, transitive]","ex":{"en":"We all herded on to the bus.","cn":"我们全都拥上公共汽车。"},"pos":"verb"},{"en":"to keep or look after a group of animals; to make animals move together as a group","cn":"牧放（牲畜）；把（牲畜）赶到一起","g":"[transitive]","ex":{"en":"a shepherd herding his flock","cn":"正在放羊的羊倌"},"pos":"verb"}]}}});
